//   1. ez a fajl              -> `PP_FORD_SZOTAR.pl`   (szoveg-egyezes)
//   2. `i18n/vagyon-pl.js`    -> `PP_VAGYON_SZOTAR.pl` (Vagyon modul, KET azonos fajlban)
//   3. `PP_SZOTAR.pl`         -> az index.html-be agyazva (`data-i18n` elemek)
