  // ===== 2026-11-02 Gerah escrow + weekly goal (owner TG 33434/33435, decision A TG 1322, card 8ed3c59e; the daily item is the signed wording) =====
  "Napi Bibliaolvasás, heti céllal. Minden nap, amikor eléred a napra beállított olvasási célodat, Gerah kerül letétbe a cél hossza szerint: legalább 10 perces cél után 1, legalább 20 perces után 2, legalább 30 perces után 3; az 5 perces cél után nem jár. Naponta legfeljebb 3 gerah. A letét akkor kerül a tárcádba, ha 7 egymást követő napon eléred a napi célodat. Ha egy nap kimarad, a letét elvész, és a hét nap elölről indul. A Gerah-t a PrepperPapa alkalmazás tárcája tárolja: a Wordlightban végzett olvasásért akkor jár, ha nálad telepítve van a PrepperPapa alkalmazás. A reggeli ébresztős felolvasás is beleszámít.": "Codzienne czytanie Biblii z celem tygodniowym. Każdego dnia, w którym osiągniesz cel czytania ustawiony na ten dzień, Gerah trafia do depozytu według długości celu: 1 za cel co najmniej 10 minut, 2 za co najmniej 20 minut, 3 za co najmniej 30 minut; cel 5 minut nie daje nic. Najwyżej 3 gerah dziennie. Depozyt trafia do twojego portfela, gdy osiągniesz dzienny cel przez 7 kolejnych dni. Jeśli opuścisz dzień, depozyt przepada, a 7 dni zaczyna się od nowa. Gerah jest przechowywana w portfelu aplikacji PrepperPapa: za czytanie w Wordlight dostajesz ją tylko wtedy, gdy na twoim urządzeniu jest zainstalowana aplikacja PrepperPapa. Czytanie budzika porannego też się liczy.",
