  // Igazitas finomhangolasa (Fonok kerese 2026-10-05 20:52)
  "Finomhangolás":
    "Dostrajanie",
  "Alaphelyzet":
    "Reset",
  "A saját térkép a helyén van.":
    "Twoja własna mapa jest na miejscu.",
  // UJ PONT felvevo a terkepen (Fonok kerese 2026-10-05 20:37)
  "Új pont":
    "Nowy punkt",
  "Menedék":
    "Schronienie",
