  "szól erre a készülékre, nincs lejárata és nincs megújítás. Ha kódot kaptál, itt válthatod be.": "dotyczy tego urządzenia, bez terminu ważności i bez odnawiania. Jeśli dostałeś kod, tutaj możesz go zrealizować.",
