  "A mai napért {n} gerah járna, de még nincs Gerah-tárcád, ezért nem került letétbe. Hozd létre a tárcádat mielőbb, hogy a mai nap is letétbe kerülhessen.": "Za dzisiejszy dzień należałoby się {n} gerah, ale nie masz jeszcze portfela Gerah, więc nic nie trafiło do depozytu. Utwórz portfel jak najszybciej, aby dzisiejszy dzień też mógł trafić do depozytu.",
  "Eddig összesen {n} gerah-t kaphattál volna a PrepperPapa alkalmazásban.": "Do tej pory mógłbyś zdobyć łącznie {n} gerah w aplikacji PrepperPapa.",
  "A mai napot a PrepperPapa alkalmazás veszi át, amikor legközelebb megnyitod. Ha a nap csatlakozik a heti cél egymást követő napjaihoz, {n} gerah kerül érte letétbe, és a heti cél teljesítésekor a tárcádba.": "Dzisiejszy dzień przejmie aplikacja PrepperPapa, gdy następnym razem ją otworzysz. Jeśli dzień dołącza do kolejnych dni twojego celu tygodniowego, {n} gerah trafi za niego do depozytu, a po osiągnięciu celu tygodniowego do twojego portfela.",
  "Ha ezen a telefonon telepíted, a telepítés napjától a Wordlightban teljesített napokat is átveszi: azokért, amelyek csatlakoznak a heti cél egymást követő napjaihoz, ott Gerah jár.": "Jeśli zainstalujesz ją na tym telefonie, od dnia instalacji przejmie także dni ukończone w Wordlight: za te, które dołączają do kolejnych dni twojego celu tygodniowego, otrzymasz tam Gerah.",
  "Wordlight — Biblia, internet nélkül is.": "Wordlight — Biblia, także bez internetu.",
  "A kód a fiókodhoz kötődik: lépj be, utána nyomd meg újra a Kód beváltása gombot.": "Kod jest przypisany do Twojego konta: zaloguj się, a potem ponownie naciśnij Zrealizuj kod.",
  "A visszajelzés küldéséhez be kell lépned. Belépés után küldd el újra.": "Aby wysłać opinię, musisz się zalogować. Po zalogowaniu wyślij ją ponownie.",
  "Ámen": "Amen",
  "Gratulálok!": "Gratulacje!",
  "Ma is {n} percet töltöttél Isten beszédével.": "Również dziś spędziłeś {n} min ze Słowem Bożym.",
  "Köszönöm": "Dziękuję",
  "Részletek": "Szczegóły",
  "{n} perc": "{n} min",
  "Nincs cél": "Bez celu",
  "Szótár: Strong-féle héber és görög szótár (1894), közkincs.": "Słownik: słownik hebrajski i grecki Stronga (1894), domena publiczna.",
  "Szótár: Strong-féle héber és görög szótár (1894), közkincs; a szótár szövege gépi fordítás.": "Słownik: słownik hebrajski i grecki Stronga (1894), domena publiczna; tekst słownika jest tłumaczeniem maszynowym.",
  "Ehhez a fordításhoz még nincs eredeti szó adat.": "Dla tego przekładu nie ma jeszcze danych o słowach oryginału.",
