// ===== 2026-11-01 prayer room: the 4-week cycle of 28 guided prayers + "Imádság a világért" (text: Énok; owner TG 32765-32783) =====
Object.assign(window.PP_FORD_SZOTAR.pl, {
  "Imádság a világért": "Modlitwa za świat",
  "Mind a 28 vezetett ima": "Wszystkie 28 modlitw z przewodnikiem",
  "{n}. hét": "Tydzień {n}",
  "Ezen a héten": "W tym tygodniu",
  "Négy hét, minden napra egy rövid vezetett ima, a kör négyhetente ismétlődik. Mindegyik hálaadással kezdődik, és csenddel zárul.": "Cztery tygodnie, na każdy dzień krótka modlitwa z przewodnikiem; cykl powtarza się co cztery tygodnie. Każda zaczyna się od dziękczynienia i kończy ciszą.",
  "Megnyitás a térképen": "Otwórz na mapie",
  "A térkép világhelyzet-adatából, frissítve {kor}.": "Z danych mapy o sytuacji na świecie, zaktualizowano {kor}.",
  "Köszönd meg a hetet, ami mögötted van. Nevezz meg három konkrét dolgot, amiért hálás vagy.": "Podziękuj za tydzień, który masz za sobą. Wymień trzy konkretne rzeczy, za które jesteś wdzięczny.",
  "Uram, köszönöm a mögöttem lévő hetet, a jót is és azt is, amit még nem értek. Köszönöm, hogy nem engedted el a kezemet. Hálás vagyok azért a három dologért, amit most eléd hozok.": "Panie, dziękuję Ci za tydzień, który mam za sobą, za to, co dobre, i za to, czego jeszcze nie rozumiem. Dziękuję, że nie puściłeś mojej ręki. Jestem wdzięczny za te trzy rzeczy, które teraz przynoszę przed Ciebie.",
  "Uram, voltak napok, amikor nélküled indultam, és nélküled döntöttem. Nem mentegetem magam, hanem eléd teszem. Köszönöm, hogy Jézusért megbocsátasz, és tisztán állhatok előtted.": "Panie, były dni, kiedy wyruszałem bez Ciebie i decydowałem bez Ciebie. Nie usprawiedliwiam się, lecz składam to przed Tobą. Dziękuję, że ze względu na Jezusa przebaczasz mi i mogę stać przed Tobą czysty.",
  "Uram, te mondod: csendesedjetek. Elcsendesedek, és elismerem, hogy te vagy az Isten, nem én. Te vagy az, aki a zaj fölött is úr marad.": "Panie, Ty mówisz: Uspokójcie się. Uspokajam się i uznaję, że Ty jesteś Bogiem, nie ja. To Ty pozostajesz Panem także ponad całym zgiełkiem.",
  "Uram, eléd teszem a jövő hetet: a munkámat, a családomat és a döntéseket, amik várnak rám. Nem kérem, hogy minden könnyű legyen, azt kérem, hogy te vezess benne. Add, hogy felismerjem a hangodat, amikor szólsz.": "Panie, składam przed Tobą przyszły tydzień: moją pracę, moją rodzinę i decyzje, które na mnie czekają. Nie proszę, aby wszystko było łatwe; proszę, abyś Ty mnie w tym prowadził. Spraw, abym rozpoznał Twój głos, gdy mówisz.",
  "Uram, itt vagyok. Nem mondok többet, csak előtted maradok.": "Panie, oto jestem. Nic więcej nie mówię, po prostu trwam przed Tobą.",
  "Uram, mielőtt bármit kérnék, köszönöm, amit már adtál. Köszönöm az otthonomat, az erőmet és azokat az embereket, akik mellettem állnak. Nem magától értetődő, ajándék.": "Panie, zanim o cokolwiek poproszę, dziękuję Ci za to, co już mi dałeś. Dziękuję za mój dom, za moje siły i za ludzi, którzy stoją przy mnie. To nie jest oczywiste, to dar.",
  "Uram, voltak gondok, amiket úgy cipeltem, mintha te nem látnád. Bocsásd meg, hogy a félelmemnek jobban hittem, mint neked. Most leteszem őket a kezedbe.": "Panie, były troski, które dźwigałem tak, jakbyś Ty ich nie widział. Przebacz mi, że bardziej uwierzyłem swojemu lękowi niż Tobie. Teraz składam je w Twoje ręce.",
  "Uram, te nem azt mondod, hogy ne legyenek gondjaim, hanem hogy hozzam őket eléd. Imádsággal, kéréssel és hálával jövök, ahogy mondtad. Te békességet ígérsz, nem magyarázatot, és ez nekem elég.": "Panie, Ty nie mówisz, że nie będę miał zmartwień, ale że mam je przynosić do Ciebie. Przychodzę z modlitwą, z prośbą i z dziękczynieniem, tak jak powiedziałeś. Obiecujesz pokój, nie wyjaśnienia, i to mi wystarcza.",
  "Uram, egyenként hozom eléd, ami ma a vállamon van. Mindegyiket rád bízom, nem azért, mert kicsik, hanem mert te nagy vagy. Őrizd meg a szívemet és a gondolataimat a Krisztus Jézusban.": "Panie, jedno po drugim przynoszę Ci to, co dziś leży na moich barkach. Wszystko Tobie powierzam, nie dlatego, że to drobiazgi, ale dlatego, że Ty jesteś wielki. Strzeż mojego serca i moich myśli w Chrystusie Jezusie.",
  "Uram, ami még bennem maradt, azt is tudod. Átadom szavak nélkül is.": "Panie, Ty znasz również to, co jeszcze we mnie zostało. Oddaję Ci to, nawet bez słów.",
  "Uram, köszönöm, hogy nem azt kapom, amit megérdemlek, hanem kegyelmet. Köszönöm, hogy Jézus már megfizetett azért, amit én nem tudtam volna. Ezért jöhetek most eléd félelem nélkül.": "Panie, dziękuję, że nie dostaję tego, na co zasługuję, lecz łaskę. Dziękuję, że Jezus już zapłacił za to, czego ja nigdy nie zdołałbym spłacić. Dlatego mogę teraz przyjść do Ciebie bez lęku.",
  "Uram, mutasd meg, mi az, amit rendbe kell tennem. Néven nevezem előtted, nem szépítem és nem magyarázom. Te hű és igaz vagy: megbocsátasz, és megtisztítasz minden hamisságtól.": "Panie, pokaż mi, co muszę naprawić. Nazywam to przed Tobą po imieniu, nie upiększam i nie tłumaczę się. Ty jesteś wierny i sprawiedliwy: przebaczasz i oczyszczasz mnie z wszelkiej nieprawości.",
  "Uram, a te szavad azt mondja: ha megvallom, megbocsátod. Nem a jó érzésemre építek, hanem a te hűségedre. Elfogadom, hogy ami megvallva van, az el is van rendezve.": "Panie, Twoje Słowo mówi: jeśli wyznam, Ty przebaczasz. Nie opieram się na swoich odczuciach, lecz na Twojej wierności. Przyjmuję, że to, co zostało wyznane, zostało też załatwione.",
  "Uram, adj erőt, hogy ahol embertől kell bocsánatot kérnem, megtegyem. És adj szívet, hogy annak is megbocsássak, aki engem bántott. Tedd rendbe, amit én már nem tudok.": "Panie, daj mi siłę, abym tam, gdzie powinienem przeprosić człowieka, zrobił to. I daj mi serce, abym przebaczył także temu, kto mnie zranił. Napraw to, czego ja już nie potrafię naprawić.",
  "Uram, tiszta lappal indulok. Köszönöm.": "Panie, zaczynam z czystą kartą. Dziękuję.",
  "Uram, köszönöm a mai napot, a reggelt, az ételt az asztalon, a tetőt a fejem fölött. Köszönöm a kicsiket is, amiket észre sem veszek. Mindegyik tőled jött.": "Panie, dziękuję Ci za dzisiejszy dzień, za poranek, za jedzenie na stole, za dach nad głową. Dziękuję też za drobiazgi, których nawet nie zauważam. Wszystko to pochodzi od Ciebie.",
  "Uram, tudom, mi került az első helyre nálam az utóbbi időben, és az nem te voltál. Megvallom, hogy a figyelmemet és az időmet máshová adtam. Bocsáss meg, és segíts újra sorba rakni.": "Panie, wiem, co ostatnio zajęło u mnie pierwsze miejsce, i nie byłeś to Ty. Wyznaję, że swoją uwagę i swój czas oddawałem gdzie indziej. Przebacz mi i pomóż mi na nowo ułożyć wszystko we właściwej kolejności.",
  "Uram, te azt mondod: először az országodat és az igazságodat keressem. Nem arra kérsz, hogy ne dolgozzak, hanem hogy ne a gond vezessen. Segíts úgy élni, mintha hinném, hogy te viselsz rám gondot, mert hiszem.": "Panie, Ty mówisz, abym najpierw szukał Twojego Królestwa i Twojej sprawiedliwości. Nie prosisz, żebym nie pracował, ale żeby nie troska mną kierowała. Pomóż mi żyć tak, jakbym wierzył, że Ty się o mnie troszczysz, bo w to wierzę.",
  "Uram, rakd rendbe a mai napom sorrendjét: te legyél az első, és minden más a helyére kerüljön. És eléd hozom a szükségleteimet is, mert te mondtad, hogy hozzam. Add meg, ami kell, és adj hálás szívet ahhoz, amit adsz.": "Panie, uporządkuj mój dzisiejszy dzień: Ty bądź na pierwszym miejscu, a wszystko inne niech znajdzie swoje miejsce. Przynoszę Ci też moje potrzeby, bo sam powiedziałeś, żebym je przynosił. Daj, czego potrzeba, i daj mi wdzięczne serce za to, co dajesz.",
  "Uram, a nap többi része a tiéd. Járj velem benne.": "Panie, reszta dnia należy do Ciebie. Idź w niej ze mną.",
  "Uram, köszönöm, hogy nem kell bejelentkeznem hozzád, és nem kell érdemet hoznom. Jézus miatt nyitva az út, és te nem fordulsz el. Köszönöm, hogy a trónod kegyelem trónja.": "Panie, dziękuję, że nie muszę umawiać się z Tobą na spotkanie ani przynosić zasług. Dzięki Jezusowi droga jest otwarta, a Ty się nie odwracasz. Dziękuję, że Twój tron jest tronem łaski.",
  "Uram, amiben elbuktam, azt nem rejtem el előled. A szégyen azt mondja, hogy maradjak távol, de te azt mondod, hogy jöjjek közel. Jövök, és kérem az irgalmadat.": "Panie, nie ukrywam przed Tobą tego, w czym upadłem. Wstyd mówi mi, żebym trzymał się z daleka, ale Ty mówisz, żebym się przybliżył. Przychodzę i proszę o Twoje miłosierdzie.",
  "Uram, te bizalommal hívsz, nem rettegéssel. Jézus tudja, milyen embernek lenni, ezért értesz engem. Alkalmas időben segítesz, és ez az idő most van.": "Panie, Ty wzywasz mnie z ufnością, a nie z trwogą. Jezus wie, co znaczy być człowiekiem, dlatego mnie rozumiesz. Pomagasz w stosownej chwili, a ta chwila jest teraz.",
  "Uram, most nem magamért jövök, hanem másokért. Eléd hozom a családomat, név szerint, és a barátaimat. És eléd hozom azt az embert, akiről tudom, hogy most nehéz helyzetben van: légy közel hozzá, adj neki erőt és reményt, és használj engem, ha kell.": "Panie, teraz nie przychodzę dla siebie, lecz dla innych. Przynoszę przed Ciebie moją rodzinę, każdego po imieniu, i moich przyjaciół. Przynoszę też tego człowieka, o którym wiem, że jest teraz w trudnej sytuacji: bądź blisko niego, daj mu siłę i nadzieję, a jeśli trzeba, użyj mnie.",
  "Uram, itt maradok előtted. Elég, hogy te itt vagy.": "Panie, zostaję tu przed Tobą. Wystarczy, że Ty tu jesteś.",
  "Uram, ma a hálával kezdem, és nem sietek vele. Végigmegyek a héten, és köszönöm a jó pillanatokat egyiket a másik után: egy beszélgetést, egy elvégzett munkát, egy nyugodt estét. Te voltál mindegyikben, akkor is, ha nem vettem észre.": "Panie, dziś zaczynam od wdzięczności i nie spieszę się z nią. Przechodzę przez cały tydzień i dziękuję za dobre chwile, jedną po drugiej: za rozmowę, za skończoną pracę, za spokojny wieczór. Byłeś w każdej z nich, nawet jeśli tego nie zauważyłem.",
  "Uram, voltak percek a héten, amikor zúgolódtam, és a hiányra néztem, nem rád. Bocsásd meg, és változtasd meg a szívemet. Taníts hálásnak lenni akkor is, amikor nem könnyű.": "Panie, były w tym tygodniu chwile, kiedy narzekałem i patrzyłem na to, czego brakuje, a nie na Ciebie. Przebacz mi i przemień moje serce. Naucz mnie być wdzięcznym także wtedy, gdy nie jest łatwo.",
  "Uram, te azt mondod, mindenben adjak hálát, nem mindenért, hanem mindenben. A nehézben is te vagy velem, és ezért ott is van mit köszönnöm. Ez a te akaratod, és én ezt választom.": "Panie, Ty mówisz, żebym we wszystkim dziękował: nie za wszystko, ale we wszystkim. Także w tym, co trudne, jesteś ze mną, więc i tam mam za co dziękować. Taka jest Twoja wola, i ja ją wybieram.",
  "Uram, a hétvégét is veled szeretném tölteni, ne csak a hétköznapokat. Vigyázz azokra, akikkel együtt leszek, és add, hogy jó legyek hozzájuk. Legyen pihenés és öröm is benne.": "Panie, chcę spędzić z Tobą także weekend, nie tylko dni powszednie. Strzeż tych, z którymi będę, i spraw, abym był dla nich dobry. Niech będzie w nim także odpoczynek i radość.",
  "Uram, örülök, hogy velem vagy. Csendben is ezt mondom.": "Panie, cieszę się, że jesteś ze mną. Mówię Ci to także w ciszy.",
  "Uram, köszönöm, hogy ma meg lehet állni. Köszönöm, ami ezen a héten elkészült, és köszönöm, hogy nem rajtam múlik a világ. A pihenés is tőled jön.": "Panie, dziękuję, że dziś można się zatrzymać. Dziękuję za to, co w tym tygodniu zostało ukończone, i dziękuję, że świat nie zależy ode mnie. Odpoczynek też pochodzi od Ciebie.",
  "Uram, cipelek dolgokat, amiket nem rám bíztál. Felelősséget, amit te hordozol, aggodalmat, amit te már elrendeztél. Megvallom, hogy nehezen engedem el, és most leteszem.": "Panie, dźwigam rzeczy, których mi nie powierzyłeś. Odpowiedzialność, którą Ty niesiesz, troskę, którą Ty już rozwiązałeś. Wyznaję, że trudno mi to puścić, i teraz to odkładam.",
  "Uram, te a megfáradtakat hívod, és én fáradt vagyok. Nem azt kéred, hogy előbb rendbe jöjjek, hanem hogy jöjjek. Jövök hozzád, úgy, ahogy vagyok.": "Panie, Ty wołasz utrudzonych, a ja jestem zmęczony. Nie żądasz, żebym najpierw doszedł do ładu, ale żebym przyszedł. Przychodzę do Ciebie taki, jaki jestem.",
  "Uram, adj nyugalmat a testemnek és a lelkemnek. Ami a jövő héten vár, azt is a kezedbe teszem, hogy ne most hordozzam. Újítsd meg az erőmet, ahogy csak te tudod.": "Panie, daj odpocznienie mojemu ciału i mojej duszy. To, co czeka mnie w przyszłym tygodniu, też składam w Twoje ręce, abym nie musiał dźwigać tego już teraz. Odnów moje siły, jak tylko Ty potrafisz.",
  "Uram, megpihenek nálad. Nem teszek semmit, csak itt vagyok.": "Panie, odpoczywam u Ciebie. Nic nie robię, po prostu tu jestem.",
  "Az Úr az én pásztorom": "Pan jest moim pasterzem",
  "Köszönd meg, hogy van, aki vezet, és nem egyedül kell kitalálnod az utat.": "Podziękuj, że jest Ktoś, kto cię prowadzi, i że nie musisz sam wymyślać drogi.",
  "Uram, köszönöm, hogy nem egyedül kell kitalálnom, hová megyek. Te vezetsz, te gondoskodsz, és te ismered az utat, ahol én még nem jártam. Jó a te nyájadhoz tartozni.": "Panie, dziękuję, że nie muszę sam wymyślać, dokąd idę. Ty prowadzisz, Ty się troszczysz i Ty znasz drogę, którą ja jeszcze nie szedłem. Dobrze jest należeć do Twojej owczarni.",
  "Hol mentél a magad feje után a héten, ahelyett, hogy őt követted volna? Mondd el.": "Gdzie w tym tygodniu poszedłeś własną drogą, zamiast iść za Nim? Powiedz Mu to.",
  "Uram, voltak helyek, ahová a magam feje után mentem, és nem kérdeztelek meg. Megvallom, hogy okosabbnak hittem magam a pásztoromnál. Hozz vissza, és én jövök.": "Panie, były miejsca, do których poszedłem po swojemu i nie zapytałem Cię o zdanie. Wyznaję, że uważałem się za mądrzejszego od mojego Pasterza. Sprowadź mnie z powrotem, a ja przyjdę.",
  "Olvasd el, és mondd ki saját szavaddal: ő az én pásztorom.": "Przeczytaj i powiedz własnymi słowami: On jest moim pasterzem.",
  "Uram, te vagy az én pásztorom, nem általánosságban, hanem az enyém. Ha te vezetsz, nem szűkölködöm, mert te tudod, mi kell nekem. Erre építem ezt a hetet.": "Panie, Ty jesteś moim pasterzem, nie ogólnie, ale moim. Jeśli Ty mnie prowadzisz, niczego mi nie brakuje, bo Ty wiesz, czego potrzebuję. Na tym buduję ten tydzień.",
  "Kérd, hogy a jövő héten a hangját kövesd, és hogy a sötét völgyben is érezd, hogy ott van.": "Poproś, abyś w przyszłym tygodniu szedł za Jego głosem i abyś także w ciemnej dolinie czuł, że On tam jest.",
  "Uram, add, hogy a jövő héten a te hangodat kövessem, ne a zajt. Ha völgybe vezet az út, add, hogy tudjam, ott is velem vagy. Legelőt és vizet is te adsz, rád bízom.": "Panie, spraw, abym w przyszłym tygodniu szedł za Twoim głosem, a nie za zgiełkiem. Jeśli droga poprowadzi przez dolinę, daj mi wiedzieć, że i tam jesteś ze mną. Pastwisko i wodę też Ty dajesz; Tobie to powierzam.",
  "Maradj csendben, mint aki biztonságban van.": "Trwaj w ciszy jak ktoś, kto jest bezpieczny.",
  "Uram, biztonságban vagyok nálad. Csendben maradok.": "Panie, u Ciebie jestem bezpieczny. Trwam w ciszy.",
  "Elég a kegyelem": "Łaska wystarcza",
  "Köszönd meg azokat a helyzeteket, ahol a saját erőd nem volt elég, mégis átjutottál.": "Podziękuj za te sytuacje, w których twoje własne siły nie wystarczyły, a jednak przez nie przeszedłeś.",
  "Uram, köszönöm azokat a helyzeteket, ahol a saját erőm elfogyott, és mégis átjutottam. Nem én voltam erős, te voltál. Köszönöm, hogy a gyengeségem nem akadály nálad.": "Panie, dziękuję za te sytuacje, w których skończyły się moje siły, a jednak przez nie przeszedłem. To nie ja byłem silny, to Ty. Dziękuję, że moja słabość nie jest dla Ciebie przeszkodą.",
  "Hol próbáltad a saját erődből megoldani, amit rá kellett volna bíznod? Valld meg.": "Gdzie próbowałeś rozwiązać własnymi siłami to, co powinieneś był Mu powierzyć? Wyznaj to.",
  "Uram, megvallom, hogy sokszor a magam erejéből akartam megoldani, amit neked kellett volna átadnom. Büszkeségből vagy félelemből, de nélküled. Bocsáss meg, és taníts rád támaszkodni.": "Panie, wyznaję, że często chciałem rozwiązać własnymi siłami to, co powinienem był oddać Tobie. Z dumy albo ze strachu, ale bez Ciebie. Przebacz mi i naucz mnie opierać się na Tobie.",
  "Olvasd el. Figyeld meg: Pál nem a gyengeség megszűnését kapta, hanem a kegyelmet benne.": "Przeczytaj. Zauważ: Paweł nie otrzymał końca słabości, lecz łaskę w niej.",
  "Uram, te azt mondtad Pálnak: elég neked az én kegyelmem. Nekem is ezt mondod. Nem azt ígéred, hogy elveszed a tövist, hanem hogy az erőd a gyengeségemben teljesedik ki.": "Panie, powiedziałeś Pawłowi: Wystarczy ci mojej łaski. Mnie mówisz to samo. Nie obiecujesz, że usuniesz cierń, lecz że Twoja moc doskonali się w mojej słabości.",
  "Nevezd meg a gyenge pontodat erre a hétre, és kérd, hogy ott Krisztus ereje lakjon.": "Nazwij swój słaby punkt na ten tydzień i poproś, aby właśnie tam zamieszkała moc Chrystusa.",
  "Uram, tudom, hol vagyok gyenge ezen a héten, és eléd hozom. Ott lakjon a Krisztus ereje, ahol az enyém nem elég. Nem kérem, hogy erős legyek, azt kérem, hogy te legyél erős bennem.": "Panie, wiem, gdzie w tym tygodniu jestem słaby, i przynoszę to przed Ciebie. Niech tam zamieszka moc Chrystusa, gdzie moja nie wystarcza. Nie proszę, abym był silny; proszę, abyś Ty był silny we mnie.",
  "Csendben hagyd, hogy a kegyelem elég legyen.": "W ciszy pozwól, aby łaska ci wystarczyła.",
  "Uram, elég nekem a kegyelmed. Ezt most elhiszem, és csendben maradok.": "Panie, wystarczy mi Twoja łaska. Teraz w to wierzę i trwam w ciszy.",
  "Ne félj": "Nie bój się",
  "Köszönd meg azokat a pillanatokat, amikor féltél, és ő mégis ott volt.": "Podziękuj za chwile, gdy się bałeś, a On mimo to był przy tobie.",
  "Uram, köszönöm azokat a pillanatokat, amikor féltem, és te mégis ott voltál. Köszönöm, hogy nem hagytál egyedül a félelemmel, akkor sem, amikor nem éreztelek. Visszanézve látom a kezedet.": "Panie, dziękuję za te chwile, gdy się bałem, a Ty mimo to byłeś przy mnie. Dziękuję, że nie zostawiłeś mnie samego z lękiem, nawet wtedy, gdy Cię nie czułem. Patrząc wstecz, widzę Twoją rękę.",
  "A félelem gyakran olyan döntésekhez vezet, amiket nem vállalnánk tisztán. Hol döntöttél félelemből? Mondd el neki.": "Strach często prowadzi do decyzji, pod którymi nie podpisalibyśmy się z czystym sumieniem. Gdzie zdecydowałeś ze strachu? Powiedz Mu to.",
  "Uram, megvallom, hogy voltak döntéseim, amiket a félelem hozott, nem a hit. Elhallgattam, elkerültem, halogattam, mert féltem. Bocsásd meg, és szabadíts meg a félelem uralmától.": "Panie, wyznaję, że niektóre moje decyzje podjął strach, a nie wiara. Milczałem, unikałem, odkładałem, bo się bałem. Przebacz mi i uwolnij mnie spod władzy strachu.",
  "Olvasd el, és számold meg, hány ígéret van egy versben. Mindegyik a jelenlétéből fakad.": "Przeczytaj i policz, ile obietnic jest w jednym wersecie. Każda wypływa z Jego obecności.",
  "Uram, te azt mondod: ne félj, mert veled vagyok. Nem azt mondod, hogy nincs mitől, hanem hogy te ott vagy. Megerősítesz, megsegítesz, a jobboddal támogatsz, és én ebbe kapaszkodom.": "Panie, Ty mówisz: Nie bój się, bo Ja jestem z tobą. Nie mówisz, że nie ma czego się bać, ale że Ty tam jesteś. Umacniasz mnie, pomagasz mi, podtrzymujesz mnie swoją prawicą, i tego się trzymam.",
  "Nevezd meg a legnagyobb félelmedet most, és tedd mellé a vers szavait.": "Nazwij teraz swój największy lęk i postaw obok niego słowa tego wersetu.",
  "Uram, kimondom előtted, mitől félek most a legjobban. Odateszem mellé a te szavaidat: veled vagyok, megerősítelek. Add, hogy a félelmem kisebb legyen, mint a hitem benned.": "Panie, wypowiadam przed Tobą, czego teraz najbardziej się boję. Stawiam obok tego Twoje słowa: Jestem z tobą, umacniam cię. Spraw, aby mój lęk był mniejszy niż moja wiara w Ciebie.",
  "Maradj csendben, mint akit fog a jobb kéz.": "Trwaj w ciszy jak ktoś, kogo trzyma Jego prawica.",
  "Uram, te fogsz engem, nem én téged. Ebben nyugszom meg.": "Panie, to Ty trzymasz mnie, a nie ja Ciebie. W tym znajduję spokój.",
  "Bízd rá az utadat": "Powierz Mu swoją drogę",
  "Köszönd meg azokat a döntéseket, amiket utólag nézve ő igazgatott.": "Podziękuj za decyzje, którymi, jak teraz widzisz, On kierował.",
  "Uram, köszönöm azokat a döntéseket, amikről utólag látom, hogy te igazgattad. Akkor nem értettem, most már igen. Köszönöm, hogy a kerülőutak is a te kezedben voltak.": "Panie, dziękuję za te decyzje, o których teraz wiem, że Ty nimi kierowałeś. Wtedy tego nie rozumiałem, teraz już tak. Dziękuję, że także okrężne drogi były w Twoich rękach.",
  "Hol támaszkodtál csak a saját értelmedre, és hagytad ki őt a döntésből? Valld meg.": "Gdzie polegałeś tylko na własnym rozumie i pominąłeś Go w decyzji? Wyznaj to.",
  "Uram, megvallom, hogy voltak döntéseim, amikbe nem vontalak be. Mindent kiszámoltam, csak téged nem kérdeztelek meg. Bocsáss meg, és segíts bizalommal élni, ne csak okosan.": "Panie, wyznaję, że były decyzje, w które Cię nie włączyłem. Wszystko przeliczyłem, tylko Ciebie nie zapytałem. Przebacz mi i pomóż mi żyć z ufnością, a nie tylko mądrze.",
  "Olvasd el. Nem az értelmet tiltja, hanem azt, hogy csak arra építs.": "Przeczytaj. Nie zakazuje używania rozumu, lecz opierania się tylko na nim.",
  "Uram, te adtad az értelmemet, és nem kéred, hogy eldobjam. Azt kéred, hogy ne egyedül arra építsek, hanem rád. Minden utamon számolok veled, és te igazgatod az utamat.": "Panie, Ty dałeś mi rozum i nie prosisz, żebym go odrzucił. Prosisz, żebym nie opierał się tylko na nim, lecz na Tobie. Na wszystkich moich drogach liczę się z Tobą, a Ty prostujesz moje ścieżki.",
  "Hozd eléje azt a döntést, ami most előtted áll. Kérj bölcsességet és nyitott szívet az ő irányára.": "Przynieś przed Niego decyzję, która teraz przed tobą stoi. Poproś o mądrość i o serce otwarte na Jego kierunek.",
  "Uram, eléd hozom azt a döntést, ami most előttem áll. Adj bölcsességet, és adj nyitott szívet, hogy a te irányodat elfogadjam akkor is, ha más, mint amit terveztem. Igazgasd ezt az utamat.": "Panie, przynoszę przed Ciebie decyzję, która teraz przede mną stoi. Daj mi mądrość i daj mi otwarte serce, abym przyjął Twój kierunek, nawet jeśli jest inny, niż planowałem. Prostuj tę moją drogę.",
  "Csendben engedd el a kontrollt.": "W ciszy oddaj kontrolę.",
  "Uram, az utam a tiéd. Elengedem, és rád bízom.": "Panie, moja droga należy do Ciebie. Puszczam ją i Tobie powierzam.",
  "Egymás terhét": "Brzemiona jedni drugich",
  "Köszönd meg azokat, akik a te terhedet hordozták, amikor nehéz volt.": "Podziękuj za tych, którzy nieśli twój ciężar, gdy było trudno.",
  "Uram, köszönöm azokat az embereket, akik hordozták a terhemet, amikor nehéz volt. Egy hívás, egy ima, egy segítő kéz, amikor kellett. Rajtuk keresztül te voltál ott.": "Panie, dziękuję za ludzi, którzy nieśli mój ciężar, gdy było trudno. Telefon, modlitwa, pomocna dłoń, kiedy była potrzebna. Przez nich Ty byłeś przy mnie.",
  "Kinek a terhe elől fordultál el az utóbbi időben, mert kényelmetlen volt? Mondd el.": "Od czyjego ciężaru ostatnio się odwróciłeś, bo był niewygodny? Powiedz Mu to.",
  "Uram, megvallom, hogy volt valaki, akinek a terhe elől elfordultam, mert kényelmetlen volt. Láttam, és továbbmentem. Bocsásd meg, és adj szívet, ami nem fordul el.": "Panie, wyznaję, że był ktoś, od czyjego ciężaru się odwróciłem, bo było mi niewygodnie. Widziałem i poszedłem dalej. Przebacz mi i daj mi serce, które się nie odwraca.",
  "Olvasd el. A Krisztus törvénye a szeretet: így teljesítjük be.": "Przeczytaj. Prawo Chrystusa to miłość: tak je wypełniamy.",
  "Uram, te azt mondod, hogy egymás terhét hordozzuk, és ezzel a Krisztus törvényét töltjük be. Nem szabály ez, hanem szeretet. Taníts úgy szeretni, ahogy te szerettél engem.": "Panie, Ty mówisz, abyśmy nosili brzemiona jedni drugich i w ten sposób wypełniali prawo Chrystusa. To nie przepis, to miłość. Naucz mnie kochać tak, jak Ty mnie ukochałeś.",
  "Nevezz meg három embert, akiknek most teher van a vállán. Imádkozz érte egyenként: egészségért, erőért, kiútért.": "Wymień trzy osoby, które dźwigają teraz ciężar. Módl się za nie po kolei: o zdrowie, o siłę, o wyjście z sytuacji.",
  "Uram, eléd hozok három embert, akik most terhet hordoznak. Az elsőért kérem, hogy adj neki erőt, a másodikért, hogy gyógyítsd, a harmadikért, hogy mutass neki kiutat. És ha engem akarsz használni bármelyiküknél, mutasd meg, hogyan.": "Panie, przynoszę przed Ciebie trzy osoby, które teraz dźwigają ciężar. Za pierwszą proszę, abyś dał jej siłę, za drugą, abyś ją uzdrowił, za trzecią, abyś pokazał jej wyjście. A jeśli chcesz użyć mnie przy którejkolwiek z nich, pokaż mi, jak.",
  "Csendben kérdezd meg: kihez küld ma?": "W ciszy zapytaj: do kogo On cię dziś posyła?",
  "Uram, kihez küldesz ma? Csendben várom.": "Panie, do kogo mnie dziś posyłasz? Czekam w ciszy.",
  "Ahogy ő megbocsátott": "Jak On przebaczył",
  "Köszönd meg, hogy neked megbocsáttatott, konkrétan, nem általánosságban.": "Podziękuj, że tobie zostało przebaczone, konkretnie, nie ogólnie.",
  "Uram, köszönöm, hogy megbocsátottál nekem. Nem általánosságban, hanem azt a konkrét dolgot is, ami most eszembe jut. Krisztusban elrendezted, és nem tartod számon.": "Panie, dziękuję, że mi przebaczyłeś. Nie ogólnie, ale także tę konkretną rzecz, która teraz przychodzi mi na myśl. W Chrystusie to załatwiłeś i już mi tego nie liczysz.",
  "Kire haragszol még? Mondd ki a nevét Isten előtt, és valld meg, ha keserűséget hordozol.": "Na kogo wciąż się gniewasz? Wypowiedz jego imię przed Bogiem i wyznaj, jeśli nosisz w sobie gorycz.",
  "Uram, van valaki, akire még haragszom, és a nevét most kimondom előtted. Megvallom, hogy keserűséget hordozok, és ez nem tőled van. Vedd ki a szívemből, mert magam nem tudom.": "Panie, jest ktoś, na kogo wciąż się gniewam, i teraz wypowiadam przed Tobą jego imię. Wyznaję, że noszę w sobie gorycz, a ona nie pochodzi od Ciebie. Wyjmij ją z mojego serca, bo sam nie potrafię.",
  "Olvasd el. A mérce: ahogy Isten Krisztusban nekem.": "Przeczytaj. Miara: tak, jak Bóg w Chrystusie przebaczył mnie.",
  "Uram, te azt mondod, úgy bocsássak meg, ahogy te megbocsátottál nekem Krisztusban. Ez a mérce, és én ebből élek. Nem azért bocsátok meg, mert a másik megérdemli, hanem mert én is kegyelmet kaptam.": "Panie, Ty mówisz, abym przebaczał tak, jak Ty przebaczyłeś mnie w Chrystusie. To jest miara, i z niej żyję. Nie przebaczam dlatego, że ten drugi na to zasługuje, ale dlatego, że i ja otrzymałem łaskę.",
  "Kérj erőt a megbocsátásra, és áldást arra az emberre. Ha túl nehéz, csak ezt mondd: segíts akarni.": "Poproś o siłę do przebaczenia i o błogosławieństwo dla tej osoby. Jeśli to zbyt trudne, powiedz tylko: Pomóż mi chcieć.",
  "Uram, adj erőt, hogy megbocsássak annak, akit most eléd hoztam, és áldd meg őt. Ha még nem tudom teljesen, segíts akarni. Tedd meg bennem, amit én még nem tudok megtenni.": "Panie, daj mi siłę, abym przebaczył temu, kogo teraz przed Ciebie przyniosłem, i pobłogosław go. Jeśli jeszcze nie potrafię w pełni, pomóż mi chcieć. Uczyń we mnie to, czego ja sam jeszcze nie potrafię uczynić.",
  "Csendben engedd el, ami a kezedben volt.": "W ciszy puść to, co trzymałeś w rękach.",
  "Uram, elengedem. A kezedbe teszem, nem az enyémben tartom.": "Panie, puszczam to. Składam to w Twoje ręce, nie trzymam w swoich.",
  "Megújuló erő": "Odnowiona siła",
  "Köszönd meg a hetet, és azt, hogy végigvitt rajta, akkor is, ha elfáradtál.": "Podziękuj za ten tydzień i za to, że On przeprowadził cię przez niego, nawet jeśli się zmęczyłeś.",
  "Uram, köszönöm, hogy végigvittél ezen a héten. Volt, hogy elfáradtam, de te nem fáradtál el mellettem. Köszönöm a mai napot, amikor meg lehet állni.": "Panie, dziękuję, że przeprowadziłeś mnie przez ten tydzień. Bywało, że się zmęczyłem, ale Ty nie zmęczyłeś się przy mnie. Dziękuję za dzisiejszy dzień, kiedy można się zatrzymać.",
  "Hol pótoltad a saját erőddel azt, amit tőle kellett volna várnod? Mondd el.": "Gdzie zastępowałeś własnymi siłami to, czego powinieneś był oczekiwać od Niego? Powiedz Mu to.",
  "Uram, megvallom, hogy sokszor a saját erőmből próbáltam pótolni azt, amit tőled kellett volna várnom. Hajtottam, mert nem bíztam. Bocsásd meg, és taníts várni rád.": "Panie, wyznaję, że często próbowałem własnymi siłami zastąpić to, czego powinienem był oczekiwać od Ciebie. Goniłem, bo Ci nie ufałem. Przebacz mi i naucz mnie czekać na Ciebie.",
  "Olvasd el lassan. Az erő azoknak újul meg, akik benne bíznak, nem akik jobban igyekeznek.": "Przeczytaj powoli. Siła odnawia się tym, którzy Mu ufają, a nie tym, którzy bardziej się starają.",
  "Uram, te azt mondod, hogy akik benned bíznak, azok ereje megújul. Nem akik jobban igyekeznek, hanem akik bíznak. Én is ezt választom: nem több erőlködés, hanem több bizalom.": "Panie, Ty mówisz, że ci, którzy ufają Tobie, odzyskują siły. Nie ci, którzy bardziej się starają, ale ci, którzy ufają. Ja też to wybieram: nie więcej wysiłku, ale więcej zaufania.",
  "Kérj megújulást a testednek, a gondolataidnak és a hitednek a jövő hétre.": "Poproś o odnowienie ciała, myśli i wiary na przyszły tydzień.",
  "Uram, újítsd meg az erőmet a jövő hétre: a testemet, a gondolataimat és a hitemet. Add, hogy ne lankadjak meg a hosszú úton, és ne fáradjak el a mindennapiban. Te vagy a forrás, nem én.": "Panie, odnów moje siły na przyszły tydzień: moje ciało, moje myśli i moją wiarę. Spraw, abym nie ustał w długiej drodze i nie zmęczył się codziennością. Ty jesteś źródłem, nie ja.",
  "Pihenj csendben, mint aki vár az Úrra.": "Odpocznij w ciszy jak ktoś, kto oczekuje Pana.",
  "Uram, várok rád. Csendben, nem sietve.": "Panie, czekam na Ciebie. W ciszy, bez pośpiechu.",
  "Világosságom és üdvösségem": "Moje światło i zbawienie",
  "Köszönd meg, hogy van világosságod, amikor minden más sötét.": "Podziękuj, że masz światło, gdy wszystko inne jest ciemne.",
  "Uram, köszönöm, hogy te vagy a világosságom, amikor körülöttem sötét van. Köszönöm, hogy az üdvösségem nem rajtam áll, hanem rajtad. Jó ezt egy vasárnap reggel kimondani.": "Panie, dziękuję, że Ty jesteś moim światłem, gdy wokół mnie jest ciemno. Dziękuję, że moje zbawienie nie zależy ode mnie, lecz od Ciebie. Dobrze jest wypowiedzieć to w niedzielny poranek.",
  "Mitől remegtél a héten, ami nagyobbnak látszott, mint Isten? Valld meg.": "Przed czym drżałeś w tym tygodniu, co wydawało się większe niż Bóg? Wyznaj to.",
  "Uram, megvallom, hogy voltak dolgok a héten, amik nagyobbnak látszottak, mint te. Remegtem tőlük, mintha te nem lennél az erősségem. Bocsáss meg, és állítsd helyre bennem az arányokat.": "Panie, wyznaję, że były w tym tygodniu sprawy, które wydawały się większe od Ciebie. Drżałem przed nimi, jakbyś Ty nie był twierdzą mojego życia. Przebacz mi i przywróć we mnie właściwe proporcje.",
  "Olvasd el, és válaszolj a kérdésre: kitől féljek?": "Przeczytaj i odpowiedz na pytanie: kogo miałbym się lękać?",
  "Uram, te kérdezed: kitől féljek? És a válasz az, hogy senkitől, mert te vagy az életem erőssége. Nem azért, mert bátor vagyok, hanem mert a tiéd vagyok.": "Panie, Ty pytasz: kogo miałbym się lękać? A odpowiedź brzmi: nikogo, bo Ty jesteś twierdzą mojego życia. Nie dlatego, że jestem odważny, ale dlatego, że należę do Ciebie.",
  "Kérd, hogy a jövő héten a te világosságában lásd a dolgokat, és hogy a házában lakjon a szíved.": "Poproś, abyś w przyszłym tygodniu widział sprawy w Jego świetle i aby twoje serce mieszkało w Jego domu.",
  "Uram, add, hogy a jövő héten a te világosságodban lássam a dolgokat, ne a félelem fényében. Legyen a szívem otthon nálad, akármerre jár a testem. Ezt kérem egyedül.": "Panie, spraw, abym w przyszłym tygodniu widział sprawy w Twoim świetle, a nie w świetle lęku. Niech moje serce ma dom u Ciebie, dokądkolwiek pójdzie moje ciało. O to jedno proszę.",
  "Maradj csendben az ő világosságában.": "Trwaj w ciszy w Jego świetle.",
  "Uram, a világosságodban vagyok. Itt maradok.": "Panie, jestem w Twoim świetle. Tu zostaję.",
  "A Lélek gyümölcse": "Owoc Ducha",
  "Köszönd meg, hogy a Szentlélek benned lakik, és nem egyedül kell jóvá lenned.": "Podziękuj, że Duch Święty w tobie mieszka i że nie musisz sam stawać się dobrym.",
  "Uram, köszönöm, hogy a Szentlelked bennem lakik, és nem egyedül kell jóvá lennem. Köszönöm, hogy a változás nem az én görcsös igyekezetem, hanem a te munkád bennem.": "Panie, dziękuję, że Twój Duch Święty we mnie mieszka i że nie muszę sam stawać się dobrym. Dziękuję, że przemiana nie jest moim kurczowym wysiłkiem, lecz Twoim dziełem we mnie.",
  "A kilenc gyümölcsből melyik hiányzott a legjobban a hétvégén? Mondd el.": "Którego z dziewięciu owoców najbardziej brakowało w weekend? Powiedz Mu to.",
  "Uram, végignézem a Lélek gyümölcseit, és tudom, melyik hiányzott a hétvégén. Kimondom előtted, mi volt az. Bocsásd meg, és ne hagyd, hogy ez legyen a végső szó rólam.": "Panie, przyglądam się owocom Ducha i wiem, którego brakowało w weekend. Wypowiadam przed Tobą, co to było. Przebacz mi i nie pozwól, by to było ostatnie słowo o mnie.",
  "Olvasd el lassan a kilenc szót. Melyiket kéri tőled Isten ezen a héten?": "Przeczytaj powoli te dziewięć słów. Którego z nich Bóg oczekuje od ciebie w tym tygodniu?",
  "Uram, kilenc szót olvasok, és mindegyik a te természeted. Nem én termelem, a te Lelked termi bennem, ha vele járok. Mutasd meg, melyiket akarod ezen a héten növelni bennem.": "Panie, czytam dziewięć słów, a każde z nich to Twoja natura. To nie ja je wydaję, to Twój Duch rodzi je we mnie, gdy z Nim idę. Pokaż mi, które chcesz w tym tygodniu we mnie pomnożyć.",
  "Kérd azt az egy gyümölcsöt a hétre, és nevezd meg a helyzetet, ahol szükséged lesz rá.": "Poproś o ten jeden owoc na ten tydzień i nazwij sytuację, w której będziesz go potrzebował.",
  "Uram, azt az egy gyümölcsöt kérem erre a hétre, amit most mutattál. Tudom, melyik helyzetben lesz rá szükségem, és eléd hozom azt is. Teremd meg bennem, amit én nem tudok előállítani.": "Panie, proszę na ten tydzień o ten jeden owoc, który mi teraz pokazałeś. Wiem, w jakiej sytuacji będę go potrzebował, i ją także przynoszę przed Ciebie. Wydaj we mnie to, czego ja sam nie potrafię wytworzyć.",
  "Csendben engedd, hogy a Lélek dolgozzon.": "W ciszy pozwól działać Duchowi.",
  "Uram, dolgozz bennem. Nem állok az utadba.": "Panie, działaj we mnie. Nie staję Ci na drodze.",
  "Gyors a hallásra": "Prędki do słuchania",
  "Köszönd meg azokat, akik meghallgattak téged, és azt, hogy Isten mindig meghallgat.": "Podziękuj za tych, którzy cię wysłuchali, i za to, że Bóg zawsze cię wysłuchuje.",
  "Uram, köszönöm, hogy te mindig meghallgatsz, mielőtt szólnék. És köszönöm azokat az embereket, akik meghallgattak engem, amikor beszélnem kellett. A meghallgatás ajándék, és te adod.": "Panie, dziękuję, że Ty zawsze mnie wysłuchujesz, zanim jeszcze się odezwę. I dziękuję za ludzi, którzy mnie wysłuchali, gdy potrzebowałem się wypowiedzieć. Wysłuchanie jest darem, a Ty go dajesz.",
  "Hol szóltál túl gyorsan, hol haragudtál túl hamar a héten? Nevezd meg az esetet, és valld meg.": "Gdzie w tym tygodniu odezwałeś się zbyt szybko, gdzie rozgniewałeś się zbyt pochopnie? Nazwij tę sytuację i wyznaj ją.",
  "Uram, megvallom, hogy voltak percek, amikor gyorsabban szóltam, mint hallgattam, és hamarabb haragudtam, mint értettem. Egy konkrét eset most eszembe jut, és eléd teszem. Bocsásd meg, és adj szelíd nyelvet.": "Panie, wyznaję, że były chwile, gdy szybciej mówiłem, niż słuchałem, i szybciej się gniewałem, niż rozumiałem. Przychodzi mi teraz na myśl konkretna sytuacja i składam ją przed Tobą. Przebacz mi i daj mi łagodny język.",
  "Olvasd el a három sorrendet: gyors, késedelmes, késedelmes. Melyik a te gyenge pontod?": "Przeczytaj trzy wskazówki: prędki, nieskory, nieskory. Która z nich to twój słaby punkt?",
  "Uram, te azt kéred: gyors legyek a hallásra, késedelmes a szólásra és a haragra. Tudom, hol vagyok ebben gyenge. Taníts először téged hallgatni, aztán az embereket, és csak utána szólni.": "Panie, Ty prosisz, abym był prędki do słuchania, nieskory do mówienia i nieskory do gniewu. Wiem, gdzie jestem w tym słaby. Naucz mnie najpierw słuchać Ciebie, potem ludzi, a dopiero potem mówić.",
  "Kérj türelmes szívet a mai beszélgetéseidhez, és egy konkrét emberhez, akivel nehezen beszélsz.": "Poproś o cierpliwe serce na dzisiejsze rozmowy i wobec jednej konkretnej osoby, z którą trudno ci rozmawiać.",
  "Uram, adj türelmes szívet a mai beszélgetésekhez. Van valaki, akivel nehezen beszélek, őt külön eléd hozom: segíts meghallgatnom, mielőtt válaszolok. Legyen a szavam békesség, ne tűz.": "Panie, daj mi cierpliwe serce na dzisiejsze rozmowy. Jest ktoś, z kim trudno mi rozmawiać; jego przynoszę przed Ciebie osobno: pomóż mi go wysłuchać, zanim odpowiem. Niech moje słowo niesie pokój, a nie ogień.",
  "Csendben hallgass, ez a gyakorlat maga.": "Słuchaj w ciszy, to właśnie jest to ćwiczenie.",
  "Uram, hallgatlak. Most nem beszélek.": "Panie, słucham Cię. Teraz nic nie mówię.",
  "Nézd a madarakat": "Spójrzcie na ptaki",
  "Köszönd meg a mindennapi gondviselést: az ételt, a munkát, a hónap végéig kitartó erőt.": "Podziękuj za codzienną opiekę: za jedzenie, za pracę, za siły, które wystarczyły do końca miesiąca.",
  "Uram, köszönöm a mindennapi gondviselésedet: az ételt az asztalon, a munkát, ami van, és az erőt, ami kitartott a hónap végéig. Nem magamnak köszönhetem, neked.": "Panie, dziękuję za Twoją codzienną opiekę: za jedzenie na stole, za pracę, którą mam, i za siły, które wystarczyły do końca miesiąca. Nie sobie to zawdzięczam, lecz Tobie.",
  "Hol aggódtál a jövő miatt úgy, mintha az Atya elfelejtett volna? Mondd el.": "Gdzie martwiłeś się o przyszłość tak, jakby Ojciec o tobie zapomniał? Powiedz Mu to.",
  "Uram, megvallom, hogy aggódtam a jövő miatt, mintha elfelejtettél volna. Számoltam, forgattam, nem aludtam, és közben nem néztem rád. Bocsásd meg a kishitűségemet.": "Panie, wyznaję, że martwiłem się o przyszłość, jakbyś o mnie zapomniał. Liczyłem, obracałem to w głowie, nie spałem, a przez cały ten czas nie patrzyłem na Ciebie. Przebacz mi moją małą wiarę.",
  "Olvasd el. Figyeld meg a kérdést a végén: nem vagytok-e sokkal különbek?": "Przeczytaj. Zwróć uwagę na pytanie na końcu: czyż wy nie jesteście ważniejsi niż one?",
  "Uram, te a madarakra mutatsz, és azt kérdezed, nem vagyok-e sokkal különb azoknál. A te gyermeked vagyok, nem csak a teremtményed. Ha őket eltartod, engem sem hagysz el.": "Panie, wskazujesz na ptaki i pytasz, czy nie jestem ważniejszy niż one. Jestem Twoim dzieckiem, nie tylko Twoim stworzeniem. Skoro je żywisz, mnie też nie opuścisz.",
  "Hozd eléje az anyagi és gyakorlati gondjaidat, egyenként, és kérd, hogy ő tartson el.": "Przynieś przed Niego swoje troski materialne i praktyczne, jedną po drugiej, i poproś, aby On cię utrzymał.",
  "Uram, eléd hozom az anyagi és gyakorlati gondjaimat, egyenként, ahogy vannak. Nem kérek fölösleget, azt kérem, hogy te tarts el, ahogy a madarakat. Adj munkát a kezemnek, és bizalmat a szívemnek.": "Panie, przynoszę przed Ciebie moje troski materialne i praktyczne, jedną po drugiej, takie, jakie są. Nie proszę o nadmiar; proszę, abyś Ty mnie utrzymywał, tak jak ptaki. Daj pracę moim rękom i zaufanie mojemu sercu.",
  "Csendben nézz ki az ablakon, vagy képzeld el: ő gondot visel.": "W ciszy wyjrzyj przez okno albo wyobraź sobie: On się troszczy.",
  "Uram, te gondot viselsz rám. Csendben ezt hagyom bennem leülepedni.": "Panie, Ty troszczysz się o mnie. W ciszy pozwalam, by ta prawda we mnie osiadła.",
  "Imádság a vezetőkért": "Modlitwa za przywódców",
  "Köszönd meg a békét, amiben élsz, a rendet, ami működik, és azokat, akik szolgálnak benne.": "Podziękuj za pokój, w którym żyjesz, za porządek, który działa, i za tych, którzy w nim służą.",
  "Uram, köszönöm a békét, amiben élek, és a rendet, ami működik körülöttem, akkor is, ha nem tökéletes. Köszönöm azokat, akik ebben szolgálnak, az orvosokat, a tanárokat, a tisztviselőket. Rajtuk keresztül is gondot viselsz.": "Panie, dziękuję za pokój, w którym żyję, i za porządek, który działa wokół mnie, nawet jeśli nie jest doskonały. Dziękuję za tych, którzy w nim służą: za lekarzy, nauczycieli, urzędników. Także przez nich się o nas troszczysz.",
  "Hol ítéltél vagy szidtál vezetőket imádság helyett? Valld meg.": "Gdzie osądzałeś lub krytykowałeś przywódców, zamiast się za nich modlić? Wyznaj to.",
  "Uram, megvallom, hogy könnyebben szidtam a vezetőket, mint imádkoztam értük. Ítéltem ott, ahol könyörögnöm kellett volna. Bocsásd meg, és adj szívet, ami inkább kér, mint vádol.": "Panie, wyznaję, że łatwiej było mi krytykować przywódców, niż się za nich modlić. Osądzałem tam, gdzie powinienem był się wstawiać. Przebacz mi i daj mi serce, które raczej prosi, niż oskarża.",
  "Olvasd el. Mindenek előtt: ez a sorrend. És mindenkiért, nem csak azokért, akiket kedvelünk.": "Przeczytaj. Przede wszystkim: taka jest kolejność. I za wszystkich, nie tylko za tych, których lubimy.",
  "Uram, te azt kéred, hogy mindenekelőtt imádkozzak minden emberért, a vezetőkért is. Nem azért, mert egyetértek velük, hanem mert te így akarod. Ez nem politika, ez közbenjárás.": "Panie, prosisz, abym przede wszystkim modlił się za wszystkich ludzi, także za przywódców. Nie dlatego, że się z nimi zgadzam, ale dlatego, że Ty tego chcesz. To nie polityka, to wstawiennictwo.",
  "Imádkozz a saját országod vezetőiért, a településedért, a gyülekezeted vezetőiért, és azokért, akik háborús országokban döntenek.": "Módl się za przywódców swojego kraju, za swoją miejscowość, za przywódców swojego kościoła oraz za tych, którzy podejmują decyzje w krajach ogarniętych wojną.",
  "Uram, eléd hozom azokat, akik az országomat vezetik, bármilyen oldalon állnak: adj nekik bölcsességet, igazságot és félelmet tőled. Imádkozom a településemért és azokért, akik ott döntenek. Imádkozom a gyülekezetem vezetőiért, hogy hűek maradjanak. És imádkozom azokért, akik háborús országokban döntenek életről és halálról: fordítsd a szívüket a béke felé.": "Panie, przynoszę przed Ciebie tych, którzy rządzą moim krajem, bez względu na to, po której stronie stoją: daj im mądrość, sprawiedliwość i bojaźń przed Tobą. Modlę się za moją miejscowość i za tych, którzy tam podejmują decyzje. Modlę się za przywódców mojego kościoła, aby pozostali wierni. I modlę się za tych, którzy w krajach ogarniętych wojną decydują o życiu i śmierci: zwróć ich serca ku pokojowi.",
  "Csendben kérj békét, hogy nyugodalmas életet élhessünk.": "W ciszy poproś o pokój, abyśmy mogli wieść spokojne życie.",
  "Uram, adj békét, hogy csendes és nyugodalmas életet élhessünk. Ámen.": "Panie, daj pokój, abyśmy mogli wieść ciche i spokojne życie. Amen.",
  "A reménység Istene": "Bóg nadziei",
  "Péntek van, a hála napja. Köszönd meg a hét öt jó pillanatát, és köszönd meg a reménységet, ami nem tőled függ.": "Jest piątek, dzień wdzięczności. Podziękuj za pięć dobrych chwil tego tygodnia i za nadzieję, która nie zależy od ciebie.",
  "Uram, végigmegyek a héten, és megköszönöm az öt legjobb pillanatát, egyiket a másik után. És köszönöm, hogy a reménységem nem a körülményeimtől függ, hanem tőled. Te vagy a reménység Istene.": "Panie, przechodzę przez cały tydzień i dziękuję za pięć jego najlepszych chwil, jedną po drugiej. I dziękuję, że moja nadzieja nie zależy od okoliczności, lecz od Ciebie. Ty jesteś Bogiem nadziei.",
  "Hol engedted el a reményt a héten, és hol lett belőle keserű beszéd? Mondd el.": "Gdzie w tym tygodniu porzuciłeś nadzieję i gdzie zamieniła się ona w gorzkie słowa? Powiedz Mu to.",
  "Uram, megvallom, hogy voltak percek, amikor elengedtem a reményt, és keserű lett a beszédem. Nem hittem, hogy változhat bármi. Bocsásd meg, és töltsd meg újra a szívemet.": "Panie, wyznaję, że były chwile, gdy porzuciłem nadzieję, a moje słowa stały się gorzkie. Nie wierzyłem, że cokolwiek może się zmienić. Przebacz mi i napełnij na nowo moje serce.",
  "Olvasd el. Az öröm és a békesség a hitből jön, a reménység a Lélek erejéből.": "Przeczytaj. Radość i pokój płyną z wiary, a nadzieja z mocy Ducha.",
  "Uram, te a reménység Istene vagy, és örömmel, békességgel töltesz be a hitben. Nem én termelem a reményt, a Lelked adja. Hadd bővölködjek benne, ne csak megéljek.": "Panie, Ty jesteś Bogiem nadziei i napełniasz mnie radością i pokojem w wierze. To nie ja wytwarzam nadzieję, daje ją Twój Duch. Pozwól mi obfitować w nią, a nie tylko jakoś przetrwać.",
  "Kérj reménységet egy konkrét ügyben, ami most reménytelennek látszik.": "Poproś o nadzieję w jednej konkretnej sprawie, która teraz wydaje się beznadziejna.",
  "Uram, van egy ügy, ami most reménytelennek látszik, és eléd hozom. Adj reménységet benne, nem vak optimizmust, hanem a te Lelked erejét. Mutasd meg, hol vagy benne te.": "Panie, jest sprawa, która teraz wydaje się beznadziejna, i przynoszę ją przed Ciebie. Daj mi w niej nadzieję, nie ślepy optymizm, lecz moc Twojego Ducha. Pokaż mi, gdzie Ty w niej jesteś.",
  "Csendben hagyd, hogy a béke betöltsön.": "W ciszy pozwól, aby pokój cię napełnił.",
  "Uram, töltsd be a szívemet békével. Csendben várom.": "Panie, napełnij moje serce pokojem. Czekam w ciszy.",
  "Vizsgálj meg": "Zbadaj mnie",
  "Köszönd meg, hogy Isten teljesen ismer, és mégis szeret.": "Podziękuj, że Bóg zna cię całkowicie, a mimo to cię kocha.",
  "Uram, köszönöm, hogy teljesen ismersz, a gondolataimat is, és mégis szeretsz. Előtted nem kell szerepet játszanom. Ez a legnagyobb nyugalom, ami egy hét végén létezik.": "Panie, dziękuję, że znasz mnie całkowicie, także moje myśli, a mimo to mnie kochasz. Przed Tobą nie muszę grać żadnej roli. To największy spokój, jaki istnieje na koniec tygodnia.",
  "Kérd, hogy ő mutassa meg, mit nem látsz magadban. Várj, és ami eszedbe jut, azt valld meg.": "Poproś, aby pokazał ci, czego w sobie nie widzisz. Czekaj, a to, co przyjdzie ci na myśl, wyznaj.",
  "Uram, vizsgálj meg, és mutasd meg, mit nem látok magamban. Nem védekezem, várok. Ami most eszembe jut, azt megvallom, és kérem, hogy tisztítsd ki belőlem.": "Panie, zbadaj mnie i pokaż mi, czego w sobie nie widzę. Nie bronię się, czekam. To, co teraz przychodzi mi na myśl, wyznaję i proszę, abyś mnie z tego oczyścił.",
  "Olvasd el lassan. Ez egy bizalmi kérés: aki szeret, azt engedjük vizsgálni.": "Przeczytaj powoli. To prośba pełna zaufania: temu, kto nas kocha, pozwalamy się badać.",
  "Uram, Dávid azt kérte, hogy vizsgáld meg, és én is ezt kérem. Nem félek a tekintetedtől, mert tudom, hogy szeretettel nézel. Vezess az örökkévalóság útján, ne csak a mai napon át.": "Panie, Dawid prosił, abyś go zbadał, i ja też o to proszę. Nie boję się Twojego spojrzenia, bo wiem, że patrzysz z miłością. Prowadź mnie drogą wieczną, nie tylko przez dzisiejszy dzień.",
  "Kérd, hogy a jövő héten ott vezessen, ahol a legkönnyebb letérni.": "Poproś, aby w przyszłym tygodniu prowadził cię tam, gdzie najłatwiej zboczyć.",
  "Uram, tudom, hol a legkönnyebb letérnem a jövő héten, és eléd hozom. Ott vezess, ott tarts meg. Add, hogy a szívem ne menjen oda, ahová a lábam már ne lépjen.": "Panie, wiem, gdzie w przyszłym tygodniu najłatwiej mi zboczyć, i przynoszę to przed Ciebie. Tam mnie prowadź, tam mnie zachowaj. Spraw, aby moje serce nie szło tam, dokąd moja noga nie powinna już stąpać.",
  "Csendben hagyd, hogy ő nézzen rád, és pihenj ebben.": "W ciszy pozwól, aby On na ciebie patrzył, i odpocznij w tym.",
  "Uram, nézz rám. Én csendben maradok a tekinteted alatt.": "Panie, spójrz na mnie. Trwam w ciszy pod Twoim spojrzeniem.",
  "Hálaadással a kapuin": "Z dziękczynieniem w Jego bramy",
  "Vasárnap van. Lépj be hálával: köszönd meg, aki ő, nem csak azt, amit ad.": "Jest niedziela. Wejdź z wdzięcznością: podziękuj za to, kim On jest, nie tylko za to, co daje.",
  "Uram, hálaadással lépek eléd ezen a reggelen. Köszönöm, aki vagy: hű, jó, irgalmas, a kezdettől a végig ugyanaz. Nem csak az ajándékaidat áldom, hanem a nevedet.": "Panie, tego poranka staję przed Tobą z dziękczynieniem. Dziękuję Ci za to, kim jesteś: wierny, dobry, miłosierny, od początku do końca ten sam. Błogosławię nie tylko Twoje dary, ale Twoje imię.",
  "Mi tart vissza attól, hogy teljes szívvel dicsérd? Mondd el neki.": "Co powstrzymuje cię przed tym, by chwalić Go całym sercem? Powiedz Mu to.",
  "Uram, tudom, mi tart vissza attól, hogy teljes szívvel dicsérjelek. Fáradtság, sértődés, vagy egy el nem rendezett dolog. Eléd teszem, hogy ne álljon a kapuban.": "Panie, wiem, co powstrzymuje mnie przed tym, by chwalić Cię całym sercem. Zmęczenie, uraza albo jakaś niezałatwiona sprawa. Składam to przed Tobą, aby nie stało w bramie.",
  "Olvasd el. Kapu, tornác, hála, dicséret: egyre közelebb visz hozzá.": "Przeczytaj. Brama, dziedziniec, dziękczynienie, chwała: każde z nich prowadzi cię bliżej Niego.",
  "Uram, te hívsz, hogy a kapuidon hálaadással, az udvarodba dicsérettel lépjek be. Minden lépés közelebb visz hozzád. Áldom a nevedet, mert te vagy az Isten.": "Panie, wzywasz mnie, abym w Twoje bramy wchodził z dziękczynieniem, a na Twoje dziedzińce z chwałą. Każdy krok przybliża mnie do Ciebie. Błogosławię Twoje imię, bo Ty jesteś Bogiem.",
  "Kérj a gyülekezetedért, a mai istentiszteletért, és azokért, akik ma nem tudnak eljönni.": "Módl się za swój kościół, za dzisiejsze nabożeństwo i za tych, którzy dziś nie mogą przyjść.",
  "Uram, eléd hozom a gyülekezetemet és a mai istentiszteletet: szólj, és add, hogy halljuk. Imádkozom azokért, akik ma nem tudnak eljönni, mert betegek vagy távol vannak. Légy velük ott, ahol vannak.": "Panie, przynoszę przed Ciebie mój kościół i dzisiejsze nabożeństwo: przemów i spraw, abyśmy usłyszeli. Modlę się za tych, którzy dziś nie mogą przyjść, bo są chorzy lub daleko. Bądź z nimi tam, gdzie są.",
  "Maradj csendben az ő udvarában.": "Trwaj w ciszy na Jego dziedzińcu.",
  "Uram, itt vagyok az udvarodban. Jó itt lenni.": "Panie, jestem tu, na Twoim dziedzińcu. Dobrze jest tu być.",
  "Mint az Úrnak": "Jak dla Pana",
  "Köszönd meg a munkádat, azt is, ami fárasztó. Ez a hely, ahol szolgálhatsz.": "Podziękuj za swoją pracę, także za tę, która męczy. To miejsce, gdzie możesz służyć.",
  "Uram, köszönöm a munkámat, azt is, ami fárasztó és láthatatlan. Köszönöm, hogy van mit tennem, és van, aki számít rá. Ez a hely, ahol téged szolgálhatlak.": "Panie, dziękuję za moją pracę, także za tę, która męczy i której nikt nie widzi. Dziękuję, że mam co robić i że ktoś na mnie liczy. To jest miejsce, gdzie mogę Ci służyć.",
  "Hol dolgoztál csak a látszatért, vagy csak félszívvel? Valld meg.": "Gdzie pracowałeś tylko na pokaz albo bez serca? Wyznaj to.",
  "Uram, megvallom, hogy voltak napok, amikor csak a látszatért dolgoztam, vagy félszívvel. Embereknek akartam megfelelni, nem neked. Bocsásd meg, és fordítsd a szívemet feléd a munkámban.": "Panie, wyznaję, że były dni, gdy pracowałem tylko na pokaz albo bez serca. Chciałem zadowolić ludzi, nie Ciebie. Przebacz mi i zwróć moje serce ku Tobie w mojej pracy.",
  "Olvasd el. Mint az Úrnak: ez az egyetlen szó megváltoztatja a hétfőt.": "Przeczytaj. Jak dla Pana: te słowa zmieniają cały poniedziałek.",
  "Uram, amit ma teszek, azt neked teszem, nem embereknek. Ez a mondat megváltoztatja a hétfőmet. A legkisebb feladat is istentisztelet, ha neked végzem.": "Panie, to, co dziś robię, robię dla Ciebie, a nie dla ludzi. To zdanie zmienia mój poniedziałek. Nawet najmniejsze zadanie jest służbą Bogu, gdy wykonuję je dla Ciebie.",
  "Hozd eléje a hét munkáját, a nehéz feladatot, és azokat, akikkel dolgozol.": "Przynieś przed Niego pracę tego tygodnia, trudne zadanie i tych, z którymi pracujesz.",
  "Uram, eléd hozom a hét munkáját és azt a feladatot, ami a legnehezebb lesz. Adj hozzá erőt és tiszta szándékot. Áldd meg azokat, akikkel együtt dolgozom, és add, hogy jó legyen velem dolgozni.": "Panie, przynoszę przed Ciebie pracę tego tygodnia i zadanie, które będzie najtrudniejsze. Daj mi do niego siłę i czyste intencje. Błogosław tym, z którymi pracuję, i spraw, aby dobrze się ze mną pracowało.",
  "Csendben ajánld fel a napot neki.": "W ciszy ofiaruj Mu ten dzień.",
  "Uram, ez a nap a tiéd. Lélekből, neked.": "Panie, ten dzień należy do Ciebie. Z serca, dla Ciebie.",
  "Békesség, amit a világ nem ad": "Pokój, jakiego świat nie daje",
  "Köszönd meg azt a békességet, amit megéltél, amikor emberileg nem volt rá ok.": "Podziękuj za pokój, którego doświadczyłeś, gdy po ludzku nie było ku temu powodu.",
  "Uram, köszönöm azokat a pillanatokat, amikor békém volt, pedig emberileg nem volt rá ok. Az a te békességed volt, nem az enyém. Köszönöm, hogy nem a világtól függ.": "Panie, dziękuję za te chwile, gdy miałem pokój, choć po ludzku nie było ku temu powodu. To był Twój pokój, nie mój. Dziękuję, że nie zależy od świata.",
  "Mi nyugtalanítja a szívedet? Mondd el, és valld meg, ha a békességet máshol kerested: a kontrollban, a zajban, a menekülésben.": "Co niepokoi twoje serce? Powiedz Mu to i wyznaj, jeśli szukałeś pokoju gdzie indziej: w kontroli, w hałasie, w ucieczce.",
  "Uram, megvallom, mi nyugtalanítja a szívemet, és azt is, hogy a békét máshol kerestem: a kontrollban, a zajban, a menekülésben. Nem tőled vártam. Bocsásd meg, és add vissza a békédet.": "Panie, wyznaję, co niepokoi moje serce, i to, że szukałem pokoju gdzie indziej: w kontroli, w hałasie, w ucieczce. Nie od Ciebie go oczekiwałem. Przebacz mi i przywróć mi Twój pokój.",
  "Olvasd el. Nem úgy, ahogy a világ adja: ez a különbség.": "Przeczytaj. Nie tak, jak daje świat: na tym polega różnica.",
  "Uram, te azt mondod, az én békességemet adom nektek, nem úgy, ahogy a világ adja. A világ békéje a baj hiánya, a tiéd a te jelenléted a bajban. Ezt kérem, nem a másikat.": "Panie, Ty mówisz: Pokój mój daję wam, nie tak, jak daje świat. Pokój świata to brak kłopotów, Twój to Twoja obecność w kłopotach. O ten proszę, nie o tamten.",
  "Kérd a békességét egy konkrét helyzetre, ami most feszültséget okoz.": "Poproś o Jego pokój w jednej konkretnej sytuacji, która teraz budzi napięcie.",
  "Uram, van egy helyzet, ami most feszültséget okoz, és eléd hozom. Add bele a te békességedet, amit nem lehet elvenni. Ne nyugtalankodjék a szívem, és ne féljen.": "Panie, jest sytuacja, która teraz budzi we mnie napięcie, i przynoszę ją przed Ciebie. Włóż w nią Twój pokój, którego nikt nie może odebrać. Niech się nie trwoży moje serce i niech się nie lęka.",
  "Csendben fogadd el a békességét.": "W ciszy przyjmij Jego pokój.",
  "Uram, elfogadom a békességedet. Csendben maradok benne.": "Panie, przyjmuję Twój pokój. Trwam w nim w ciszy.",
  "Lámpás az úton": "Lampa na drodze",
  "Köszönd meg, hogy van Igéd, és hogy olvashatod, hallgathatod, amikor akarod.": "Podziękuj, że masz Słowo Boże i że możesz je czytać i słuchać, kiedy chcesz.",
  "Uram, köszönöm, hogy van Igéd, és hogy itt van nálam, olvashatom és hallgathatom, amikor akarom. Sokaknak ez nem adatott meg. Köszönöm, hogy szólsz rajta keresztül.": "Panie, dziękuję, że mam Twoje Słowo, że jest tu przy mnie i mogę je czytać i słuchać, kiedy chcę. Wielu ludzi tego nie ma. Dziękuję, że przez nie mówisz.",
  "Mikor tetted le az Igét, és indultál el a saját fényednél? Mondd el.": "Kiedy odłożyłeś Słowo i ruszyłeś w drogę przy własnym świetle? Powiedz Mu to.",
  "Uram, megvallom, hogy sokszor letettem az Igédet, és a saját fényemnél indultam el. Aztán csodálkoztam, hogy sötét van. Bocsásd meg, és hozz vissza a lámpásodhoz.": "Panie, wyznaję, że często odkładałem Twoje Słowo i ruszałem w drogę przy własnym świetle. A potem dziwiłem się, że jest ciemno. Przebacz mi i przyprowadź mnie z powrotem do Twojej lampy.",
  "Olvasd el. A lámpás a következő lépést mutatja, nem az egész utat.": "Przeczytaj. Lampa pokazuje następny krok, nie całą drogę.",
  "Uram, a te Igéd lámpás a lábamnak. Nem az egész utat mutatja, csak a következő lépést, és ez elég. Taníts megelégedni annyi fénnyel, amennyit ma adsz.": "Panie, Twoje Słowo jest lampą dla moich stóp. Nie pokazuje całej drogi, tylko następny krok, i to wystarczy. Naucz mnie poprzestawać na tym świetle, które dajesz mi dzisiaj.",
  "Kérd, hogy egy konkrét kérdésben az Igéből kapj irányt, és hogy legyen időd olvasni a héten.": "Poproś, abyś w jednej konkretnej sprawie otrzymał kierunek ze Słowa i abyś miał w tym tygodniu czas na czytanie.",
  "Uram, van egy kérdés, amiben irányt várok, és kérem, hogy az Igéden keresztül szólj bele. Adj időt és csendet a héten, hogy olvassalak, ne csak kapkodjak. Legyen a te szavad az első, amit meghallok.": "Panie, jest sprawa, w której czekam na kierunek, i proszę, abyś przemówił do niej przez Twoje Słowo. Daj mi w tym tygodniu czas i ciszę, abym czytał Twoje Słowo, a nie tylko się spieszył. Niech Twoje słowo będzie pierwszym, które usłyszę.",
  "Csendben hagyd, hogy a világosság rád essen.": "W ciszy pozwól, aby padło na ciebie światło.",
  "Uram, világíts az ösvényemre. Csendben követlek.": "Panie, oświetl moją ścieżkę. Idę za Tobą w ciszy.",
  "Erősek az Úrban": "Mocni w Panu",
  "Köszönd meg, hogy a harc már eldőlt a kereszten, és te az ő erejében állsz.": "Podziękuj, że bitwa została już rozstrzygnięta na krzyżu i że stoisz w Jego mocy.",
  "Uram, köszönöm, hogy a döntő harcot te már megnyerted a kereszten. Nem én harcolok a győzelemért, hanem a győzelemből állok meg. Köszönöm a fegyverzetet, amit nem én gyártottam.": "Panie, dziękuję, że rozstrzygającą bitwę już wygrałeś na krzyżu. Nie walczę o zwycięstwo, lecz stoję, bo zwycięstwo już jest. Dziękuję za zbroję, której nie ja wykułem.",
  "Hol harcoltál emberek ellen, amikor nem ők voltak az igazi ellenség? Valld meg.": "Gdzie walczyłeś z ludźmi, choć to nie oni byli prawdziwym wrogiem? Wyznaj to.",
  "Uram, megvallom, hogy emberek ellen harcoltam, pedig te azt mondod, nem test és vér ellen van a harcunk. Haraggal válaszoltam ott, ahol imádkozni kellett volna. Bocsásd meg, és nyisd meg a szememet.": "Panie, wyznaję, że walczyłem z ludźmi, choć Ty mówisz, że nasza walka nie toczy się przeciwko ciału i krwi. Odpowiadałem gniewem tam, gdzie powinienem był się modlić. Przebacz mi i otwórz moje oczy.",
  "Olvasd el. Erősek az Úrban, nem magunkban. Megállni, nem rohamozni.": "Przeczytaj. Mocni w Panu, nie w sobie. Ostać się, nie szturmować.",
  "Uram, te azt mondod, legyek erős az Úrban, a te hatalmas erődben, nem a magaméban. Felöltözöm, amit adsz: az igazságot, a hitet, a békesség evangéliumát. Nem rohamozok, megállok.": "Panie, Ty mówisz, abym był mocny w Panu, w potężnej Twojej mocy, nie we własnej. Przywdziewam to, co dajesz: prawdę, wiarę, ewangelię pokoju. Nie szturmuję, ostoję się.",
  "Imádkozz közbenjárva: a családodért, hogy megálljanak, a gyülekezetedért, a kísértésben lévő testvéredért, és az üldözött keresztényekért.": "Módl się, wstawiając się: za rodzinę, aby wytrwała, za swój kościół, za brata w wierze, który przeżywa pokusę, i za prześladowanych chrześcijan.",
  "Uram, imádkozom a családomért, hogy megálljanak a hitben, és te őrizd őket. Imádkozom a gyülekezetemért, hogy egy legyen és erős. Eléd hozom azt a testvéremet, akiről tudom, hogy kísértésben van: tarts meg őt. És imádkozom az üldözött keresztényekért a világban, hogy hűek maradjanak, és te légy nekik pajzs.": "Panie, modlę się za moją rodzinę, aby wytrwała w wierze, i proszę, strzeż jej. Modlę się za mój kościół, aby był zjednoczony i silny. Przynoszę przed Ciebie mojego brata w wierze, o którym wiem, że przeżywa pokusę: zachowaj go. I modlę się za prześladowanych chrześcijan na świecie, aby pozostali wierni, a Ty bądź dla nich tarczą.",
  "Csendben állj meg az ő erejében.": "W ciszy stań w Jego mocy.",
  "Uram, a te erődben állok. Megállok, és te tartasz.": "Panie, stoję w Twojej mocy. Stoję, a Ty mnie podtrzymujesz.",
  "Minden reggel megújul": "Odnawia się każdego ranka",
  "A hála napja. Köszönd meg a hét minden reggelét, hogy felkelhettél, és azt, hogy ő minden reggel ugyanaz volt.": "Dzień wdzięczności. Podziękuj za każdy poranek tego tygodnia, za to, że mogłeś wstać, i za to, że On każdego ranka był taki sam.",
  "Uram, köszönöm a hét minden reggelét, hogy felkelhettem, és hogy te minden reggel ugyanaz voltál. Köszönöm a kegyelmedet, ami nem fogyott el, pedig én sokszor elfogytam. Nagy a te hűséged.": "Panie, dziękuję za każdy poranek tego tygodnia, za to, że mogłem wstać, i za to, że Ty każdego ranka byłeś taki sam. Dziękuję za Twoją łaskę, która się nie wyczerpała, choć ja często byłem u kresu sił. Wielka jest Twoja wierność.",
  "Hol kételkedtél a hűségében a héten, mert a körülmény mást mondott? Mondd el.": "Gdzie w tym tygodniu zwątpiłeś w Jego wierność, bo okoliczności mówiły co innego? Powiedz Mu to.",
  "Uram, megvallom, hogy voltak percek a héten, amikor a körülmény mást mondott, mint te, és én a körülménynek hittem. Kételkedtem a hűségedben. Bocsásd meg, te hű maradtál akkor is.": "Panie, wyznaję, że były w tym tygodniu chwile, gdy okoliczności mówiły co innego niż Ty, a ja uwierzyłem okolicznościom. Zwątpiłem w Twoją wierność. Przebacz mi; Ty i wtedy pozostałeś wierny.",
  "Olvasd el. Ez a mondat romok közül hangzik, ezért igaz a te romjaid közt is.": "Przeczytaj. To zdanie zabrzmiało wśród ruin, dlatego jest prawdziwe także wśród twoich ruin.",
  "Uram, ezt a mondatot valaki romok közt mondta ki, és azért igaz az én romjaim közt is. A te irgalmad nem fogyatkozik el, minden reggel megújul. Erre építem a következő reggelt is.": "Panie, te słowa ktoś wypowiedział wśród ruin, i dlatego są prawdziwe także wśród moich ruin. Twoje miłosierdzie się nie kończy, odnawia się każdego ranka. Na tym buduję także następny poranek.",
  "Kérd, hogy az ő hűsége legyen az, amire a hétvégén építesz, és nem a saját hangulatod.": "Poproś, aby to Jego wierność była tym, na czym budujesz w weekend, a nie twój nastrój.",
  "Uram, add, hogy a hétvégén a te hűségedre építsek, ne a hangulatomra. Újítsd meg a kegyelmedet a holnapi reggelre is, és add, hogy észrevegyem. Te vagy az, akiben nincs változás.": "Panie, spraw, abym w weekend budował na Twojej wierności, a nie na swoim nastroju. Odnów swoją łaskę także na jutrzejszy poranek i spraw, abym ją zauważył. Ty jesteś Tym, w którym nie ma zmienności.",
  "Csendben nyugodj meg a hűségében.": "W ciszy odpocznij w Jego wierności.",
  "Uram, nagy a te hűséged. Ebben nyugszom meg.": "Panie, wielka jest Twoja wierność. W niej znajduję spokój.",
  "Aki elkezdte, elvégzi": "Ten, który rozpoczął, dokończy",
  "Nézz vissza az elmúlt négy hétre. Köszönd meg, amit Isten elkezdett benned, akkor is, ha még nincs kész.": "Spójrz wstecz na ostatnie cztery tygodnie. Podziękuj za to, co Bóg w tobie rozpoczął, nawet jeśli to jeszcze nie jest skończone.",
  "Uram, visszanézek az elmúlt hetekre, és köszönöm, amit elkezdtél bennem. Nincs kész, de elkezdted, és ez a tiéd. Köszönöm, hogy nem hagytad abba, amikor én abbahagytam volna.": "Panie, patrzę wstecz na ostatnie tygodnie i dziękuję za to, co we mnie rozpocząłeś. To jeszcze nie jest skończone, ale Ty to rozpocząłeś, i to jest Twoje. Dziękuję, że nie przestałeś, gdy ja bym już przestał.",
  "Hol adtad fel magad, mintha a befejezés rajtad állna? Valld meg.": "Gdzie się poddałeś, jakby dokończenie zależało od ciebie? Wyznaj to.",
  "Uram, megvallom, hogy voltak percek, amikor feladtam magamat, mintha a befejezés rajtam állna. Elfelejtettem, hogy a munka a tiéd. Bocsásd meg, és emeld fel újra a fejemet.": "Panie, wyznaję, że były chwile, gdy się poddawałem, jakby dokończenie zależało ode mnie. Zapomniałem, że to dzieło jest Twoje. Przebacz mi i podnieś znowu moją głowę.",
  "Olvasd el lassan. Aki elkezdte, az végzi el. Nem te.": "Przeczytaj powoli. Kto rozpoczął, ten dokończy. Nie ty.",
  "Uram, te kezdted el bennem a jó dolgot, és te végzed el a Krisztus Jézus napjáig. Nem én tartom magam a kezedben, te tartasz engem. Ebben a bizonyosságban zárom a hetet.": "Panie, Ty rozpocząłeś we mnie dobre dzieło i dokończysz je aż do dnia Chrystusa Jezusa. To nie ja trzymam się w Twoich rękach, to Ty mnie trzymasz. W tej pewności zamykam ten tydzień.",
  "Kérd, hogy a következő hetekben is folytassa benned a munkáját, és nevezd meg, hol szeretnél növekedni.": "Poproś, aby także w kolejnych tygodniach kontynuował w tobie swoje dzieło, i nazwij, w czym chciałbyś wzrastać.",
  "Uram, folytasd bennem a munkádat a következő hetekben is. Tudom, hol szeretnék növekedni, és eléd hozom, de rád bízom, hogy mit és milyen sorrendben formálsz. A te időd a jó idő.": "Panie, kontynuuj we mnie swoje dzieło także w kolejnych tygodniach. Wiem, w czym chciałbym wzrastać, i przynoszę to przed Ciebie, ale Tobie zostawiam, co i w jakiej kolejności we mnie kształtujesz. Twój czas jest dobrym czasem.",
  "Pihenj csendben abban, hogy Isten keze van rajtad, és ő nem engedi el.": "Odpocznij w ciszy w tym, że Boża ręka spoczywa na tobie i On cię nie puści.",
  "Uram, a te kezed van rajtam, és te nem engedsz el. Csendben megpihenek ebben. Ámen.": "Panie, Twoja ręka spoczywa na mnie i Ty mnie nie puścisz. W ciszy odpoczywam w tym. Amen.",
  "Most emeld fel a tekintetedet a saját ügyeidről a világra. Ezek az események most történnek, és ott emberek vannak.": "Teraz podnieś wzrok znad własnych spraw na świat. Te wydarzenia dzieją się teraz, a tam są ludzie.",
  "Uram, most nem magamért kérek, hanem azokért, akiket nem ismerek, de te igen. Eléd hozom a világ bajait, amik ma történnek.": "Panie, teraz nie proszę za siebie, lecz za tych, których nie znam, ale Ty ich znasz. Przynoszę przed Ciebie nieszczęścia świata, które dzieją się dzisiaj.",
  "Uram, te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Hadd legyél az nekik is ma. Ámen.": "Panie, Ty jesteś naszą ucieczką i siłą, pomocą w utrapieniach najpewniejszą. Bądź tym dla nich także dzisiaj. Amen.",
  "Most nem tudjuk, mi történik épp a világban, de valahol most is baj van. Imádkozz azokért, akikről ma nem szól a hír.": "Teraz nie wiemy, co dokładnie dzieje się na świecie, ale gdzieś właśnie teraz jest nieszczęście. Módl się za tych, o których dziś nie mówią wiadomości.",
  "Uram, nem tudom, hol van ma a legnagyobb baj a világon, de te tudod. Eléd hozom azokat, akik ebben az órában földrengésben, árvízben, tűzben vagy háborúban vannak, és akikről nem szól a hír. Légy az oltalmuk, adj nekik segítséget és vigaszt, és fordítsd a világ szívét a béke felé. Te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Ámen.": "Panie, nie wiem, gdzie dziś na świecie jest największe nieszczęście, ale Ty wiesz. Przynoszę przed Ciebie tych, którzy w tej godzinie przeżywają trzęsienie ziemi, powódź, pożar lub wojnę, i o których nie mówią wiadomości. Bądź ich ucieczką, daj im pomoc i pocieszenie, i zwróć serce świata ku pokojowi. Ty jesteś naszą ucieczką i siłą, pomocą w utrapieniach najpewniejszą. Amen.",
  // Imádság a világért, per event (Énok, ima-vilag-rovid.json, owner 2026-11-02 TG 33947-33954): encouragement + prayer, news labels
  "Amikor a föld megrendül, Isten nem rendül meg. Az imád most valódi kéz lehet a romok fölött.": "Gdy ziemia się trzęsie, Bóg się nie chwieje. Twoja modlitwa może być teraz prawdziwą ręką nad gruzami.",
  "A víz gyorsabb az embernél, de nem gyorsabb Istennél. Egy mondat most életet menthet.": "Woda jest szybsza od człowieka, ale nie od Boga. Jedno zdanie może teraz uratować życie.",
  "A tűz nem kérdez, de Isten hall. Állj oda imádságban azok mellé, akik most mindent hátrahagynak.": "Ogień nie pyta, ale Bóg słyszy. Stań w modlitwie przy tych, którzy teraz zostawiają wszystko.",
  "Isten megígérte, hogy a víz nem lesz úr a földön. Kérd ezt most azoknak, akiknek mindent elvisz.": "Bóg obiecał, że woda nie zapanuje nad ziemią. Proś o to teraz dla tych, którym zabiera wszystko.",
  "Jézus egy szóval elcsendesítette a vihart. Ugyanez a szó ma is érvényes, mondd ki értük.": "Jezus jednym słowem uciszył burzę. To słowo jest ważne i dziś, wypowiedz je za nich.",
  "A hegyek Isten kezében vannak. Imádkozz, hogy az emberek időben induljanak, és legyen hová menniük.": "Góry są w ręku Boga. Módl się, by ludzie wyruszyli na czas i mieli dokąd pójść.",
  "Az aszály csendes baj, ritkán szól róla a hír. Te most mégis eléje viheted Istennek.": "Susza to cicha klęska, rzadko w wiadomościach. A jednak możesz ją teraz przynieść przed Boga.",
  "Jézus gyógyító keze ma sem rövidült meg. Állj oda a betegek és az ápolók mellé.": "Uzdrawiająca ręka Jezusa i dziś nie jest za krótka. Stań przy chorych i przy tych, którzy ich pielęgnują.",
  "Isten nem áll be egyik tömegbe sem, mindkét oldalon az övéit látja. Imádkozz oldal nélkül, békéért.": "Bóg nie staje w żadnym tłumie, widzi swoich po obu stronach. Módl się o pokój, bez opowiadania się po stronie.",
  "Boldogok a békességre igyekezők. Az imád ma ott lehet, ahová senki más nem jut el.": "Błogosławieni, którzy wprowadzają pokój. Twoja modlitwa może dziś dotrzeć tam, gdzie nikt inny nie dotrze.",
  "Uram, légy {hely} romjai alatt a várakozókkal, adj erőt a mentőknek, és vigasztald a gyászolókat.": "Panie, bądź z tymi, którzy czekają pod gruzami w regionie {hely}, daj siłę ratownikom i pociesz tych, którzy płaczą.",
  "Uram, tartsd vissza a vizet, és vezesd időben magaslatra a part lakóit.": "Panie, powstrzymaj wodę i prowadź mieszkańców wybrzeża na czas w wyższe miejsca.",
  "Uram, védd meg {hely} menekülőit és tűzoltóit, és küldj esőt a lángokra.": "Panie, chroń uciekających i strażaków w regionie {hely}, i ześlij deszcz na płomienie.",
  "Uram, őrizd meg {hely} lakóinak életét, és adj menedéket azoknak, akiknek otthona víz alatt áll.": "Panie, zachowaj życie ludzi w regionie {hely} i daj schronienie tym, których domy są pod wodą.",
  "Uram, csendesítsd le a szelet és a vizet {hely} fölött, ahogy a tanítványaid hajóján tetted.": "Panie, ucisz wiatr i wodę w regionie {hely}, jak uczyniłeś to w łodzi swoich uczniów.",
  "Uram, vezesd biztonságba {hely} lakóit, és adj bölcsességet azoknak, akik a kitelepítésről döntenek.": "Panie, prowadź ludzi w regionie {hely} w bezpieczne miejsce i daj mądrość tym, którzy decydują o ewakuacji.",
  "Uram, adj esőt {hely} földjére és kenyeret az asztalukra, és nyisd meg a bővölködők kezét.": "Panie, daj deszcz ziemi w regionie {hely} i chleb na stół jej mieszkańców, i otwórz ręce tych, którzy mają w obfitości.",
  "Uram, gyógyítsd {hely} betegeit, és adj erőt és védelmet az orvosoknak és ápolóknak.": "Panie, uzdrów chorych w regionie {hely} i daj siłę i ochronę lekarzom i pielęgniarkom.",
  "Uram, őrizd meg {hely} életeit mindkét oldalon, és fordítsd a szíveket a béke felé.": "Panie, zachowaj życie ludzi w regionie {hely} po każdej stronie i zwróć serca ku pokojowi.",
  "Uram, védd meg {hely} civiljeit és gyermekeit, gyógyítsd a sebesülteket, és adj békét, bármelyik oldalon állnak.": "Panie, chroń cywilów i dzieci w regionie {hely}, uzdrów rannych i daj pokój, po której stronie by nie stali.",
  "Érintett terület": "Obszar dotknięty",
  "Legnagyobb szélsebesség": "Maksymalna prędkość wiatru",
  "Események": "Zdarzenia",
  "Halálos áldozatok": "Ofiary śmiertelne",
  "Időszak": "Okres",
  "Egy földrengés után órák döntenek életekről. Imádkozz a romok alatt lévőkért és a mentőkért.": "Po trzęsieniu ziemi godziny decydują o życiu. Módl się za tych, którzy są pod gruzami, i za ratowników.",
  "Uram, eléd hozom {hely} területét, ahol megrendült a föld. Légy azokkal, akik a romok alatt várnak, és adj erőt és gyorsaságot azoknak, akik keresik őket. Vigasztald, aki ma elveszített valakit, és adj fedelet annak, akinek nem maradt.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, gdzie zatrzęsła się ziemia. Bądź z tymi, którzy czekają pod gruzami, i daj siłę i szybkość tym, którzy ich szukają. Pociesz tych, którzy dziś kogoś stracili, i daj dach nad głową tym, którym nic nie zostało.",
  "A tűz otthonokat, erdőket és életeket visz el. Imádkozz a menekülőkért és a tűzoltókért.": "Ogień zabiera domy, lasy i ludzkie życie. Módl się za uciekających i za strażaków.",
  "Uram, eléd hozom {hely} területét, ahol tűz pusztít. Védd meg azokat, akik menekülnek, és add, hogy mindenkit elérjen a figyelmeztetés időben. Adj erőt és védelmet a tűzoltóknak, és küldj esőt és szelet úgy, ahogy csak te tudod.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, gdzie szaleje ogień. Chroń tych, którzy uciekają, i spraw, aby ostrzeżenie dotarło do wszystkich na czas. Daj siłę i ochronę strażakom i ześlij deszcz i wiatr tak, jak tylko Ty potrafisz.",
  "Az árvíz lassan jön, és mindent elvisz. Imádkozz azokért, akik az otthonukat látják eltűnni.": "Powódź przychodzi powoli i zabiera wszystko. Módl się za tych, którzy patrzą, jak znika ich dom.",
  "Uram, eléd hozom {hely} lakóit, akiket elért a víz. Őrizd meg az életüket, és adj menedéket azoknak, akiknek az otthona víz alatt áll. Légy a gyerekekkel és az idősekkel, akik nem tudnak maguktól menekülni, és adj türelmet és erőt a visszatéréshez.": "Panie, przynoszę przed Ciebie mieszkańców regionu: {hely}, do których dotarła woda. Zachowaj ich życie i daj schronienie tym, których domy stoją pod wodą. Bądź z dziećmi i starszymi, którzy nie mogą sami uciec, i daj cierpliwość i siłę na powrót.",
  "A vihar előtt a várakozás, utána a kár. Imádkozz az útjában lévőkért.": "Przed burzą oczekiwanie, po niej szkody. Módl się za tych, którzy są na jej drodze.",
  "Uram, eléd hozom {hely} területét, amerre a vihar tart vagy ahol már lecsapott. Csendesítsd a szelet és a vizet, ahogy a tanítványaid hajóján tetted. Védd meg azokat, akik az útjában állnak, és adj gyors segítséget, ahol a tetők és a falak már leomlottak.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, ku któremu zmierza burza albo gdzie już uderzyła. Ucisz wiatr i wodę, jak uczyniłeś to w łodzi swoich uczniów. Chroń tych, którzy są na jej drodze, i daj szybką pomoc tam, gdzie dachy i ściany już się zawaliły.",
  "A hamu és a láva elől menekülni kell. Imádkozz a környék falvaiért és a kitelepítettekért.": "Przed popiołem i lawą trzeba uciekać. Módl się za okoliczne wsie i za ewakuowanych.",
  "Uram, eléd hozom {hely} környékét, ahol a hegy kitört. Védd meg a falvakat és a városokat a láva és a hamu útjából, és adj bölcsességet azoknak, akik a kitelepítésről döntenek. Légy azokkal, akik mindent otthagytak, és adj nekik helyet, ahol megpihenhetnek.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, gdzie wybuchła góra. Chroń wsie i miasta przed lawą i popiołem i daj mądrość tym, którzy decydują o ewakuacji. Bądź z tymi, którzy wszystko zostawili, i daj im miejsce, gdzie mogą odpocząć.",
  "Az aszály csendes katasztrófa, nincs hírverése. Imádkozz az éhezőkért és a földművesekért.": "Susza to cicha katastrofa, nikt o niej głośno nie mówi. Módl się za głodnych i za rolników.",
  "Uram, eléd hozom {hely} lakóit, ahol kiszáradt a föld, és nincs mit enni. Adj esőt a földre és kenyeret az asztalra, és nyisd meg azok kezét, akiknek bőven van. Tartsd meg a gyerekeket, és adj reményt a földműveseknek, akik újra vetnek.": "Panie, przynoszę przed Ciebie mieszkańców regionu: {hely}, gdzie wyschła ziemia i nie ma co jeść. Daj deszcz ziemi i chleb na stół, i otwórz ręce tych, którzy mają pod dostatkiem. Zachowaj dzieci i daj nadzieję rolnikom, którzy znów sieją.",
  "A háborúban mindkét oldalon emberek halnak meg. Imádkozz a civilekért, a sebesültekért és a békéért, oldal nélkül.": "Na wojnie ludzie giną po obu stronach. Módl się za cywilów, za rannych i o pokój, nie stając po żadnej stronie.",
  "Uram, eléd hozom {hely} területét, ahol fegyverek szólnak. Védd meg a civileket, a gyerekeket, az öregeket és azokat, akiknek nincs hová menniük. Gyógyítsd a sebesülteket, vigasztald a gyászolókat, és fordítsd a döntéshozók szívét a béke felé, bármelyik oldalon állnak. Te vagy a békesség Istene, hadd legyen béke ott is.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, gdzie mówi broń. Chroń cywilów, dzieci, starszych i tych, którzy nie mają dokąd pójść. Ulecz rannych, pociesz opłakujących i zwróć serca decydentów ku pokojowi, bez względu na to, po której stronie stoją. Ty jesteś Bogiem pokoju, niech i tam zapanuje pokój.",
  "Ahol tömegek feszülnek egymásnak, ott félelem és harag van mindkét oldalon. Imádkozz békéért és józanságért, oldal nélkül.": "Tam, gdzie tłumy stają naprzeciw siebie, po obu stronach jest strach i gniew. Módl się o pokój i trzeźwość, nie stając po żadnej stronie.",
  "Uram, eléd hozom {hely} területét, ahol feszültség és zavargás van az utcákon. Csendesítsd a haragot, és őrizd meg az életeket, azokét is, akik tüntetnek, és azokét is, akik rendet tartanak. Adj józanságot azoknak, akik döntenek, és add, hogy a sérelmek ne vérrel, hanem szóval oldódjanak meg.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, gdzie na ulicach panuje napięcie i zamieszki. Ucisz gniew i zachowaj życie ludzi, zarówno tych, którzy protestują, jak i tych, którzy pilnują porządku. Daj trzeźwość tym, którzy podejmują decyzje, i spraw, aby krzywdy rozwiązywano słowem, a nie krwią.",
  "A járványban a betegek és az ápolók egyformán kimerülnek. Imádkozz gyógyulásért és kitartásért.": "W czasie epidemii chorzy i ci, którzy ich pielęgnują, jednakowo opadają z sił. Módl się o uzdrowienie i wytrwałość.",
  "Uram, eléd hozom {hely} lakóit, ahol betegség terjed. Gyógyítsd a betegeket, és állítsd meg a terjedést, ahogy csak te tudod. Adj erőt és védelmet az orvosoknak és az ápolóknak, akik nem mennek haza, és vigasztald azokat, akik már elveszítettek valakit.": "Panie, przynoszę przed Ciebie mieszkańców regionu: {hely}, gdzie szerzy się choroba. Uzdrawiaj chorych i zatrzymaj jej rozprzestrzenianie się, jak tylko Ty potrafisz. Daj siłę i ochronę lekarzom i pielęgniarkom, którzy nie wracają do domu, i pociesz tych, którzy już kogoś stracili.",
  "Nem tudjuk pontosan, mi történik ott, de Isten tudja. Imádkozz azokért, akik benne vannak.": "Nie wiemy dokładnie, co się tam dzieje, ale Bóg wie. Módl się za tych, których to dotyka.",
  "Uram, eléd hozom {hely} területét, ahol most baj van, és nem is tudom pontosan, milyen. Te tudod, és te látod minden embert ott. Légy velük, védd meg az életüket, és küldj segítséget időben.": "Panie, przynoszę przed Ciebie ludzi w regionie: {hely}, gdzie teraz dzieje się coś złego, choć nawet nie wiem dokładnie co. Ty wiesz i widzisz tam każdego człowieka. Bądź z nimi, chroń ich życie i ześlij pomoc na czas.",
});

