  // READING-PLAN GERAH CONSENT (owner 2026-11-02, TG 1464 "14A")
  "Hozzájárulok, hogy az olvasási terv teljesítését (mely napon mely bibliai fejezetet olvastam) a PrepperPapa a fiókomhoz kötve tárolja a terv befejezési Gerah-ráadásához. Ez vallási meggyőződésre utaló adat lehet. A hozzájárulás bármikor visszavonható a Beállításokban.": "Wyrażam zgodę, aby PrepperPapa przechowywał powiązany z moim kontem przebieg planu czytania (którego dnia który rozdział Biblii przeczytałem) na potrzeby premii gerah za ukończenie planu. Mogą to być dane wskazujące na przekonania religijne. Zgodę można w każdej chwili wycofać w Ustawieniach.",
