// 2026-11-03: the guided prayer's encouragements (Énok, IMA_VEZ_BUZD; owner TG 34198) and the Charon voice's
// visible name (owner TG 34202-34212: Mihály, in each language its own form)
Object.assign(window.PP_FORD_SZOTAR.pl, {
  "A csend nem üresség, hanem jelenlét. Nem neked kell rendbe tenned a hetet, mielőtt Isten elé állsz: elég, ha megállsz. Ő a zaj fölött is Isten, és ma a te szívedben is az akar lenni.": "Cisza nie jest pustką, lecz obecnością. Nie musisz porządkować swojego tygodnia, zanim staniesz przed Bogiem: wystarczy, że się zatrzymasz. On jest Bogiem ponad wszelkim hałasem, i dziś chce być nim także w twoim sercu.",
  "Az aggodalom mindig a holnapban él, a hála a mában. Amikor megköszönöd, amit már kaptál, a félelemnek kevesebb helye marad. Ma ne a terhet sorold elő először, hanem azt, amit Isten már megtett.": "Troska zawsze żyje w jutrze, wdzięczność w dzisiaj. Gdy dziękujesz za to, co już otrzymałeś, lęk ma mniej miejsca. Dziś nie wyliczaj najpierw swoich ciężarów, lecz to, co Bóg już uczynił.",
  "Isten nem félig bocsát meg. Ha megvallottad, nem kell újra elővenned és újra hordoznod. Ma tiszta lappal indulsz, nem azért, mert jó voltál, hanem mert ő hű és igaz.": "Bóg nie przebacza połowicznie. Jeśli to wyznałeś, nie musisz znów tego wyciągać ani dźwigać na nowo. Dziś zaczynasz z czystą kartą, nie dlatego, że byłeś dobry, ale dlatego, że On jest wierny i sprawiedliwy.",
  "Ami először jön, az szabja meg a többit. Ha ma az ő országa kerül az első helyre, a teendőid nem tűnnek el, de a helyükre kerülnek. Bízd rá a sorrendet, és figyeld meg, mi adatik hozzá.": "To, co jest pierwsze, nadaje kształt całej reszcie. Jeśli dziś Jego królestwo znajdzie się na pierwszym miejscu, twoje obowiązki nie znikną, ale trafią na swoje miejsce. Powierz Mu kolejność i zobacz, co będzie ci przydane.",
  "Nem kell kopogtatva, lehajtott fejjel jönnöd. A kegyelem trónja elé bizalommal járulhatsz, mert Jézus már kitárta az ajtót. Amire ma szükséged van, azt kérd bátran: ez a megfelelő idő.": "Nie musisz przychodzić nieśmiało, ze spuszczoną głową. Możesz z ufnością przystąpić do tronu łaski, bo Jezus już szeroko otworzył drzwi. O to, czego dziś potrzebujesz, proś odważnie: to jest właściwy czas.",
  "A hála nem a körülményekből fakad, hanem abból, aki a körülmények fölött áll. Nem mindenért, de mindenben adhatsz hálát. Ma keresd meg azt az egy pontot a nehézségben, ahol Isten keze már látszik.": "Wdzięczność nie wypływa z okoliczności, lecz z Tego, który stoi ponad nimi. Nie za wszystko, ale we wszystkim możesz dziękować. Dziś poszukaj w trudności tego jednego miejsca, gdzie ręka Boga już jest widoczna.",
  "Jézus nem azt mondja, hogy előbb erősödj meg, és utána jöhetsz. A fáradtakat hívja. Tedd le nála, ami nyom, ne magyarázd, csak tedd le. A nyugalom nála kezdődik, nem a feladatok végén.": "Jezus nie mówi: najpierw się wzmocnij, a potem możesz przyjść. On woła spracowanych. Złóż przy Nim to, co cię przygniata, nie tłumacz się, po prostu to złóż. Odpoczynek zaczyna się przy Nim, a nie na końcu twoich zadań.",
  "Ha az Úr a pásztorod, nem egyedül kell kitalálnod az utat. Ő tudja, hol a legelő és hol a csendes víz. Ma ne a hiányt számold, hanem kövesd a hangját, és meglátod, hogy nem szűkölködsz.": "Jeśli Pan jest twoim pasterzem, nie musisz sam szukać drogi. On wie, gdzie jest pastwisko i gdzie są ciche wody. Dziś nie licz braków, lecz idź za Jego głosem, a zobaczysz, że niczego ci nie braknie.",
  "A gyengeséged nem akadály Isten előtt, hanem tér, ahol az ő ereje megmutatkozik. Ma ne szégyelld, ahol kevés vagy. Pont ott mondja neked: elég az én kegyelmem.": "Twoja słabość nie jest przeszkodą przed Bogiem, lecz przestrzenią, w której objawia się Jego moc. Dziś nie wstydź się tam, gdzie jesteś mały. Właśnie tam mówi do ciebie: Dosyć masz na łasce mojej.",
  "A félelem azt súgja, hogy egyedül vagy. Isten azt mondja: veled vagyok. Nem a félelem nagysága dönt, hanem az, hogy kinek a jobbja tart. Ma kapaszkodj abba a kézbe, ami nem enged el.": "Lęk szepcze ci, że jesteś sam. Bóg mówi: Jestem z tobą. Nie wielkość lęku decyduje, lecz to, czyja prawica cię trzyma. Dziś trzymaj się tej ręki, która cię nie puści.",
  "Nem kell mindent értened ahhoz, hogy jó úton járj. Elég, ha minden lépésnél őt ismered el. A térkép nála van, neked a következő lépés jut. Tedd meg ma bizalommal.": "Nie musisz wszystkiego rozumieć, aby iść dobrą drogą. Wystarczy, że na każdym kroku będziesz Go uznawał. Mapa jest u Niego, tobie przypada następny krok. Zrób go dziś z ufnością.",
  "Valaki ma nehezebb terhet visz, mint te. Lehet, hogy egy telefon, egy jó szó vagy egy ima az, ami könnyít rajta. Krisztus törvénye ilyen egyszerű lépésekben töltődik be. Kérdezd meg Istent: kinek kellek ma?": "Ktoś dziś niesie cięższe brzemię niż ty. Może to telefon, dobre słowo albo modlitwa ulżą mu w tym. Zakon Chrystusowy wypełnia się w tak prostych krokach. Zapytaj Boga: komu jestem dziś potrzebny?",
  "A megbocsátás nem azt jelenti, hogy nem fájt. Azt jelenti, hogy nem te viszed tovább a számlát. Ahogy Isten Krisztusban elengedte a tiédet, úgy engedheted el te is. Ma szabadabban léphetsz ki ebből az imából.": "Przebaczenie nie znaczy, że nie bolało. Znaczy, że to już nie ty niesiesz dalej ten rachunek. Jak Bóg w Chrystusie odpuścił tobie, tak i ty możesz to puścić. Dziś możesz wyjść z tej modlitwy swobodniej.",
  "A kifáradás nem bukás. Aki az Úrban bízik, annak az ereje nem egyszer adatik, hanem újra és újra megújul. Ma nem kell repülnöd, ha csak járni tudsz. Ő ott is megtart, és nem fáradsz el.": "Zmęczenie nie jest porażką. Ci, którzy ufają Panu, nie otrzymują siły tylko raz, lecz odnawia się ona wciąż na nowo. Dziś nie musisz latać, jeśli możesz tylko chodzić. On i tam cię podtrzyma, i nie ustaniesz.",
  "Ha az Úr a világosságod, a sötétség nem dönthet helyetted. Kitől féljek? Ez nem dac, hanem bizalom. Ma nézz szembe azzal, ami nyugtalanít, és mondd ki hangosan: az Úr az én életem erőssége.": "Jeśli Pan jest twoim światłem, ciemność nie może decydować za ciebie. Kogóż się mam bać? To nie przekora, lecz zaufanie. Dziś stań twarzą w twarz z tym, co cię niepokoi, i powiedz na głos: Pan jest siłą żywota mego.",
  "A Lélek gyümölcse nem erőfeszítésből terem, hanem abból, hogy közel maradsz hozzá. Nem neked kell előállítanod a békességet és a türelmet. Maradj ma a szőlőtőn, és a gyümölcs megjön.": "Owoc Ducha nie rodzi się z wysiłku, lecz z tego, że pozostajesz blisko Niego. To nie ty musisz wytworzyć pokój i cierpliwość. Trwaj dziś w winnym krzewie, a owoc przyjdzie.",
  "A legtöbb sebet nem a tett, hanem a gyors szó ejti. Ma figyelj egy kicsit tovább, mielőtt válaszolsz. Lehet, hogy a csendben meghallod, mit akar mondani a másik, és mit akar mondani Isten.": "Większość ran zadaje nie czyn, lecz pochopne słowo. Dziś posłuchaj trochę dłużej, zanim odpowiesz. Być może w ciszy usłyszysz, co chce powiedzieć drugi człowiek, i co chce powiedzieć Bóg.",
  "A madarak nem aggódnak a holnapi kenyér miatt, mégis van mit enniük. Te sokkal értékesebb vagy előtte. Ma, amikor a gond megszólal, nézz fel egy pillanatra, és emlékezz: az Atya tud rólad.": "Ptaki nie martwią się o jutrzejszy chleb, a jednak mają co jeść. Ty jesteś dla Niego o wiele cenniejszy. Dziś, gdy odezwie się troska, podnieś na chwilę wzrok i pamiętaj: Ojciec wie o tobie.",
  "A vezetőkért mondott ima nem politika, hanem szolgálat. Akár egyetértesz velük, akár nem, Isten kezében vannak. Imádkozz értük ma, hogy csendes és nyugodalmas életet élhessünk, te és a családod is.": "Modlitwa za rządzących nie jest polityką, lecz służbą. Czy się z nimi zgadzasz, czy nie, są w ręku Boga. Módl się dziś za nich, abyśmy mogli prowadzić ciche i spokojne życie, ty i twoja rodzina także.",
  "A reménység nem azon múlik, mit látsz, hanem azon, kiben hiszel. Isten nem kis adagban adja, hanem bővölködni akar benned. Ma engedd, hogy a Szentlélek töltse be azt, ami kiürült.": "Nadzieja nie zależy od tego, co widzisz, lecz od tego, w kogo wierzysz. Bóg nie daje jej w małych porcjach, lecz chce, abyś obfitował w nią. Dziś pozwól, aby Duch Święty napełnił to, co się opróżniło.",
  "Bátorság Istentől kérni, hogy vizsgáljon meg. Nem azért teszi, hogy elítéljen, hanem hogy vezessen. Ami ma előkerül, azt ne rejtsd el, add oda neki. Ő az örökkévalóság útjára akar vinni.": "Trzeba odwagi, by prosić Boga, aby cię doświadczył. Nie czyni tego, by cię potępić, lecz by cię prowadzić. Tego, co dziś wyjdzie na jaw, nie ukrywaj, oddaj Mu to. On chce cię prowadzić drogą wieczną.",
  "A hálaadás a kapu, amin bejutsz az ő jelenlétébe. Nem kell nagy szavakat keresned. Kezdd azzal, ami ma eszedbe jut, és figyeld meg, hogyan nyílik meg a szíved a dicséretre.": "Dziękczynienie jest bramą, przez którą wchodzisz w Jego obecność. Nie musisz szukać wielkich słów. Zacznij od tego, co dziś przychodzi ci na myśl, i zobacz, jak twoje serce otwiera się na uwielbienie.",
  "Nincs olyan munka, ami túl kicsi ahhoz, hogy az Úrnak végezd. A mai feladataid, a rutin is, istentisztelet lehet. Tedd ma lélekből, mintha neki tennéd, mert valójában neki teszed.": "Nie ma pracy zbyt małej, by wykonywać ją dla Pana. Twoje dzisiejsze zadania, nawet codzienna rutyna, mogą być oddawaniem Mu czci. Czyń je dziś z serca, jakby dla Niego, bo naprawdę czynisz je dla Niego.",
  "A világ békessége a körülményektől függ, Jézusé nem. Ő úgy adja, hogy a vihar közepén is megmarad. Ma, ha a szíved nyugtalan, ne a vihar elcsendesedésére várj, hanem vedd át tőle a békességét.": "Pokój świata zależy od okoliczności, pokój Jezusa nie. On daje go tak, że trwa nawet pośrodku burzy. Dziś, jeśli twoje serce jest niespokojne, nie czekaj, aż burza ucichnie, lecz przyjmij od Niego Jego pokój.",
  "Az ige nem reflektor, ami az egész utat bevilágítja, hanem lámpás a lábad elé. Elég a következő lépéshez. Ma ne a távoli kanyarokon aggódj, hanem tedd meg azt a lépést, amit most látsz.": "Słowo nie jest reflektorem, który oświetla całą drogę, lecz pochodnią dla twoich nóg. Wystarczy na następny krok. Dziś nie martw się dalekimi zakrętami, lecz zrób ten krok, który widzisz teraz.",
  "Az erő nem a te izmodból jön, hanem az ő hatalmából. Isten fegyverzete készen áll, csak fel kell öltened. Ma reggel tudatosan vedd magadra: az igazság, a hit, az ige ott van melletted.": "Siła nie pochodzi z twoich mięśni, lecz z Jego mocy. Zbroja Boża jest gotowa, musisz ją tylko przywdziać. Dziś rano przywdziej ją świadomie: prawda, wiara i słowo są przy tobie.",
  "Bármi történt tegnap, ma reggel Isten irgalma újra friss. Nem fogyott el, nem kopott meg. Ez a nap új kezdet, mert nagy az ő hűsége, és nem a tiéd tartja meg a napot.": "Cokolwiek wydarzyło się wczoraj, dziś rano miłosierdzie Boże jest znów świeże. Nie wyczerpało się, nie zużyło. Ten dzień jest nowym początkiem, bo wielka jest Jego wierność, i to nie twoja wierność podtrzymuje ten dzień.",
  "Amit Isten elkezdett benned, azt nem hagyja félbe. Lehet, hogy most nem látod a végét, de ő látja. Ma nyugodj meg abban, hogy a munka az ő kezében van, és ő elvégzi.": "To, co Bóg w tobie rozpoczął, nie zostawi niedokończonego. Może teraz nie widzisz końca, ale On go widzi. Dziś uspokój się w tym, że dzieło jest w Jego ręku, i On je dokończy.",
  "Mihály": "Michał",
});

