  "A mentés túl nagy a fiókhoz ({m} MB, legfeljebb {max} MB). Készíts helyi teljes mentést fájlba.": "Kopia jest za duża dla konta ({m} MB, najwyżej {max} MB). Zrób lokalną pełną kopię do pliku.",
