  "Igetanulmányozó ingyen naponta {db} fejezet, ma még {n}.": "Studium wersetów za darmo {db} rozdziały dziennie, dziś zostało {n}.",
  "Ma már {db} fejezetet összevetettél az igetanulmányozóban. Holnap újra jár; Biblia prémiummal korlátlanul összevetheted a fordításokat.": "Dziś porównano już {db} rozdziały w studium wersetów. Jutro znów będą dostępne; z Biblią Premium porównujesz przekłady bez limitu.",
