// THE BUILT-IN CONFESSION "Szellemi fegyverek felvétele" IN THIS LANGUAGE (Marveen 30529, Thomas 30526: the confession
// list was empty outside Hungarian). Same 27 paragraphs as the Hungarian Part 2, the same 9 pictures in the same
// paragraphs (kepek: the sentence the picture stands before / after, and the piece name set in bold). The scripture after
// "it is written" is verbatim from the Bible the app ships for this language (Uwspółcześniona Biblia Gdańska (UBG 2017)), with its reference.
window.PP_MEGV_BEEPITETT_FORD = window.PP_MEGV_BEEPITETT_FORD || {};
window.PP_MEGV_BEEPITETT_FORD.pl = {"cim": "Przywdzianie duchowej zbroi", "szoveg": "Drogi Ojcze Niebieski, dziękuję Ci za Twoją miłość. Dziękuję Ci za Twoją wierność, dziękuję Ci za życie. Dziękuję Ci za Twoje słowo, które także dziś objawiłeś, i dziękuję Ci za Twoje Słowo. Dziękuję Ci, Panie, za duchową broń, za najpotężniejszą duchową broń. Dziękuję Ci za Twojego Syna, dziękuję Ci za imię Pana Jezusa Chrystusa. Dziękuję Ci, Jezu, za Twoją krew. Dziękuję Ci, Panie, za odkupienie, dziękuję Ci, Panie, za zbawienie, za przebaczenie grzechów, za dar nawrócenia. Dziękuję Ci, Panie, że mnie odrodziłeś; błogosławię Cię, mój wieczny Królu. Dziękuję Ci, Panie, za Kościół, Ciało Chrystusa, i za moją chrześcijańską wspólnotę, część powszechnego Kościoła. Dziękuję Ci, Panie, za moich braci i siostry, za tych, których znam, i za tych, których nie znam. Dziękuję za tych, których imiona znam, i także za tych, których imion nie znam. Dziękuję Ci, Ojcze Niebieski, za mocnych w wierze i za słabych w wierze. Dziękuję Ci, Ojcze Niebieski, za tych, którzy są wolni, i także za tych, którzy są związani.\n\nOjcze, teraz staję przed Tobą i umacniam na sobie duchową broń, a także całą resztę. Przywdziewam hełm zbawienia i nadziei, i zniewalam wszelką myśl, aby każda moja myśl była posłuszna Panu Jezusowi Chrystusowi. Rozważam, jakie myśli odciągają mój umysł od Boga, i wypowiadam je na głos, aby słowo po słowie związać je w potężnym i chwalebnym imieniu Jezusa. Biorę władzę nad każdą troską, nad każdą nieczystą, rozpustną myślą: zabraniam ci błąkać się po moim umyśle, rozkazuję ci opuścić moją głowę, mój umysł. W imieniu Jezusa wychodzisz ze mnie i schodzisz ze mnie! W imieniu Jezusa biorę władzę nad wszelką religijną mgłą, otępieniem i oszołomieniem, i wiążę je. Rozkazuję ci odejść ode mnie, zejść ze mnie, wyjść ze mnie, z mojej rodziny, z mojego domu, w imieniu Pana Jezusa.\n\nW imieniu Jezusa biorę władzę nad wszelką podejrzliwością, nieufnością, zwątpieniem i sceptycyzmem wobec prawdy i wobec sług Bożych. Wiążę cię i rozkazuję ci zejść ze mnie, wyjść ze mnie, z mojej rodziny, z mojego domu, z moich relacji z ludźmi, w imieniu Jezusa! W imieniu Pana Jezusa biorę władzę nad wszelkim przerażeniem, zastraszeniem i grozą. W imieniu Pana Jezusa rozkazuję ci wyjść ze mnie, z mojej rodziny, z mojego domu, w imieniu Jezusa. Burzę, wyrzekam się i wyrzucam z mojego umysłu wszelką myśl, wszelką wyniosłość i wszelką twierdzę, która powstała przeciwko poznaniu Boga i stoi na drodze do poznania Boga. W imieniu Pana Jezusa biorę władzę, rozkazuję: precz z mojej głowy! Wszelkie kłamstwo, wiążę cię w imieniu Jezusa! Złe duchy podstępu, obłudy, nieczystości, nierządu, niewierności, cudzołóstwa, pornografii, pożądliwości, rozpusty, nudyzmu, homoseksualizmu, kazirodztwa, bezwstydu, sadyzmu i perwersji, opuśćcie moją głowę, mój umysł, moje myśli! Wychodzicie ze mnie, schodzicie ze mnie, z mojej rodziny, z mojego domu, z moich dzieci, z moich rodziców, z mojego męża / mojej żony, z moich relacji z ludźmi, z moich braci i sióstr, z mojego zboru i z mojego miasta, w potężnym, chwalebnym i świętym imieniu Jezusa, mocą Ducha Świętego!\n\nW imieniu Jezusa biorę władzę nad wszystkimi złymi duchami kłótni, rywalizacji, zazdrości, goryczy, użalania się nad sobą, przewrażliwienia, drażliwości, urazy, obrażalskości, pretensji, gniewu, jadu, złej woli, nienawiści, złośliwości, zemsty, nieprzebaczenia, morderczej wściekłości i morderczych myśli, które przychodzą przeciwko mnie i przeciwko mojemu zborowi, i wiążę je! Wiążę was i rozkazuję wam wyjść ze mnie, zejść ze mnie; odejdźcie od nas, opuśćcie nas, w potężnym i chwalebnym imieniu Jezusa, mocą Ducha Świętego!\n\nW imieniu Pana Jezusa biorę władzę nad każdym złym duchem pychy, próżności, zarozumiałości, wyniosłości, zadufania, egoizmu i egocentryzmu, który przychodzi przeciwko mnie i przeciwko mojemu zborowi; nad każdym złym duchem beznadziei, zniechęcenia, letargu, depresji, melancholii, zgryzoty, smutku, apatii, posępności, ponurości, pesymizmu i braku perspektyw! Wiążę cię i rozkazuję ci zejść ze mnie, wyjść ze mnie! Zły duchu porażki i niepowodzenia, wychodzisz z tego miejsca, schodzisz z mojej głowy, z mojego umysłu!\n\nBłogosławię cię, mój umyśle, abyś myślał o tym, co w górze, o tym, co prawdziwe, czyste, chwalebne i uczciwe. Jeśli jest jakaś cnota, jakaś pochwała, o tym myśl, mój umyśle.\n\nDziękuję Ci, Panie, że mnie odrodziłeś, że mam żywą nadzieję w Panu. Wybawiasz mnie, Panie Jezu Chryste, bo w Tobie jest moja nadzieja, pewna i mocna kotwica mojej duszy. Nadzieja mnie zachowuje, a nadzieja nie przynosi mi wstydu także dzisiaj. Czeka mnie dobra przyszłość, Panie, bo Ty, Jezu Chryste, jesteś Arcykapłanem moich przyszłych dni, moim orędownikiem, moim rzecznikiem. To Ty, Panie, prosisz i wstawiasz się za mną po prawicy Ojca. Amen. To jest hełm mojego zbawienia i mojej nadziei.\n\nW imieniu Pana Jezusa biorę władzę i przywdziewam pancerz sprawiedliwości i usprawiedliwienia. Przyoblekam się w siłę i władzę, w stanowczość, odwagę, aktywność, inicjatywę, męskość. (Kobiety niech nie mówią ostatniego słowa.) Kocham sprawiedliwość, nienawidzę nieprawości, dlatego namaściłeś mnie, Ojcze, olejkiem radości bardziej niż moich towarzyszy. Jest napisane: Duch Pana nade mną, ponieważ namaścił mnie, abym głosił ewangelię ubogim, posłał mnie, abym uzdrawiał skruszonych w sercu, abym uwięzionym zwiastował wyzwolenie, a ślepym przejrzenie, abym uciśnionych wypuścił na wolność; Abym głosił miłościwy rok Pana. (Łk 4,18-19) Chrystus jest Pomazańcem, a Chrystus jest we mnie, dlatego to wyznaję.\n\nW imieniu Pana Jezusa biorę władzę nad złym duchem oskarżania, potępienia, winy, poczucia winy, fałszywych wyrzutów sumienia, lżenia, znieważania, pogardy, pomniejszania i deprecjonowania, który przychodzi przeciwko mnie i przeciwko mojemu zborowi. Wiążę cię i rozkazuję ci w chwalebnym imieniu Jezusa: odejdź ode mnie, wyjdź ze mnie, zejdź ze mnie, odejdź od nas! Opuszczasz mnie, opuszczacie moją rodzinę, mój dom, moje miejsce pracy, moje relacje z ludźmi, mój zbór, opuszczacie nabożeństwo, w potężnym imieniu Jezusa Chrystusa, mocą Ducha Świętego.\n\nJest napisane: Dlatego teraz żadnego potępienia nie ma dla tych, którzy są w Jezusie Chrystusie, którzy nie postępują według ciała, ale według Ducha. (Rz 8,1) Jestem w Jezusie Chrystusie, żyję według Ducha i nie postępuję według ciała. Jest napisane: Któż będzie oskarżał wybranych Bożych? Bóg jest tym, który usprawiedliwia. Któż potępi? (Rz 8,33-34) Bóg mnie usprawiedliwił. Jest napisane: Ale oni zwyciężyli go przez krew Baranka i przez słowo swego świadectwa (Obj 12,11). Także dzisiaj zwyciężam oskarżyciela przez krew Baranka, mocą słowa mojego świadectwa, przez moje oddane Bogu życie. Jestem sprawiedliwością Boga, światłością świata, solą ziemi i jestem miłą wonią Chrystusa.\n\nW potężnym imieniu Pana Jezusa biorę moc i władzę nad złym duchem nieprzydatności, niegodności, poczucia niższości, odrzucenia, pomijania, wyrzucenia, wykluczenia, wyobcowania, samotności, dyskryminacji, zbędności, izolacji, frustracji i braku miłości, który przychodzi przeciwko nam i przeciwko naszemu zborowi. Wiążę cię i rozkazuję ci: odejdź ode mnie, od nas! Opuśćcie moich braci i siostry, zgromadzenie, zbór, w imieniu Jezusa Chrystusa, mocą Ducha Świętego! W imieniu Pana Jezusa jest napisane, że jestem umiłowanym dzieckiem Boga. Dlatego frustracja nie ma we mnie miejsca, bo jestem błogosławionym człowiekiem w Panu. Ufam, bo łaknę i pragnę sprawiedliwości. Pan mnie nasyca. Jestem błogosławionym człowiekiem, bo Pan mnie wybrał. Jestem błogosławionym człowiekiem, bo zapisał moje imię w księdze życia. Jestem błogosławionym człowiekiem, bo moje serce jest czyste i będę oglądać Boga, bo Pan oczyścił moje serce.\n\nW imieniu Jezusa Chrystusa biorę władzę i moc nad strachem, lękiem i grozą, które przychodzą przeciwko nam i przeciwko naszemu zborowi: nad lękiem przed odrzuceniem, porażką i upokorzeniem; nad lękiem przed wyrzuceniem, wykluczeniem i wyobcowaniem; nad lękiem przed samotnością, dyskryminacją, zbędnością i izolacją; nad lękiem przed upadkiem, śmiercią, piekłem i porażką; nad lękiem przed demonami, chorobą, przekleństwem, czarami i duszewnymi modlitwami. Biorę nad tobą władzę i wiążę cię. Rozkazuję ci: zejdź ze mnie, odejdź ode mnie, wyjdź ze mnie! Opuszczacie mnie, moich braci i siostry, moją rodzinę, mój dom i także nabożeństwo, w potężnym imieniu Pana Jezusa Chrystusa, mocą Ducha Świętego! Bo jest napisane: miłość Boga jest rozlana w naszych sercach przez Ducha Świętego, który został nam dany (Rz 5,5), oraz: doskonała miłość usuwa lęk (1J 4,18). Ta miłość wypędza, wypiera ze mnie wszelki lęk! (Wyznanie: Psalmy 27, 91, 18)\n\nPrzepasuję moje biodra prawością: szczerością, czystością, nienawiścią do grzechu, nienawiścią do zła, miłością do dobra, cierpliwością. Przyoblekam się w miłosierdzie, współczucie, dobroć, wierność, łagodność, panowanie nad sobą, pokorę, braterską życzliwość, uprzejmość i serdeczność; przyoblekam się w Chrystusa. Przyoblekam się w charakter Chrystusa, w Jego naturę, w dar i owoc Ducha Świętego.\n\nW potężnym imieniu Jezusa Chrystusa zrzucam z siebie starego człowieka wraz z jego zepsuciem, podstępnością, pożądliwościami, namiętnościami, przekleństwami, stanem przeklęcia, chorobami, słabościami, zmęczeniem, depresjami i beznadzieją. Przyoblekam się w nową naturę Chrystusa, która także dziś się odnawia, Panie Jezu Chryste, na Twój obraz i dla Twojej chwały, przez Słowo Boże i moc Ducha Świętego. Przebaczam każdemu, kto grzeszy przeciwko mnie. W imieniu Jezusa Chrystusa przebaczam następującym osobom: ………… (trzeba je wyznać i wypowiedzieć na głos ich imiona) ……. I wreszcie przebaczam także sobie.\n\nW imieniu Pana Jezusa Chrystusa biorę moc i władzę nad szatańskimi złymi duchami niemocy, słabości, niepewności, braku odwagi, nieporadności, ślamazarności, tchórzostwa, niezdecydowania, nieszczęścia, wypadków i powodowania wypadków, które przychodzą przeciwko mnie i przeciwko mojemu zborowi. Wiążę was w imieniu Pana Jezusa i rozkazuję wam odejść od nas, ode mnie, od mojej rodziny, od mojego domu, od mojego miejsca pracy, od moich współpracowników! Rozkazuję wam odejść: wszelka niecierpliwość, bezlitosność, brak współczucia, legalizm, surowość, krytykanctwo, zatwardziałość serca! Wiążę was: nieprzebaczenie, urazę, gorycz i użalanie się nad sobą! Rozkazuję ci odejść ode mnie! Opuszczacie moje życie, mój dom, moją rodzinę, moje relacje, domy, lud Boży, nabożeństwo, zbór, w imieniu Jezusa Chrystusa, mocą Ducha Świętego! Amen.\n\nBłogosławię moje nerki, każdą część mojego ciała, członków mojej rodziny, moją żonę / mojego męża, moje dzieci, moich braci i siostry oraz moich krewnych ku czystości, świętości, sprawiedliwości, zaufaniu wobec sług Bożych, posłuszeństwu. Od Ciebie, Panie, mam nowe serce, i to nowe serce jest takie jak Twoje: łagodne i pokorne. Dlatego dziedziczę ziemię, a Ty mnie wywyższasz.\n\nObuwam moje nogi w gotowość ewangelii pokoju. Postanawiam, że także dziś będę głosić dobrą nowinę, radość, pokój i wyzwolenie. Do nóg należy gonitwa. Dlatego w imieniu Pana Jezusa odkopuję od siebie przemoc, niespokojność, niepokój, gonitwę, zagonienie, demona włóczęgi, „otrutą mysz”, która nie może usiedzieć w miejscu, demona chochlika, który nigdy nie ustaje. Strącam je i wypędzam! Zobowiązuję się, że gdy wkładam to obuwie, będę mówić ewangelię Bożą z miłosierdzia, z Bożej miłości, w pokoju, i będę składać świadectwo, jeśli także dziś będzie okazja, i nie będę uciekać od tej sytuacji ani się od niej wymigiwać. Jest napisane: O jak piękne są nogi tych, którzy zwiastują ewangelię pokoju, tych, którzy opowiadają dobre rzeczy! (Rz 10,15) Dlatego moje nogi są piękne w imieniu Jezusa Chrystusa. Amen. Ale jest też napisane: Nie lubuje się w mocy konia ani nie ma upodobania w goleniach mężczyzny. (Ps 147,10)\n\nW imieniu Pana Jezusa Chrystusa biorę władzę nad każdym złym duchem braku pokoju, prześladowania, zagonienia, niepokoju, niespokojności, nerwowości, wrogości, wzniecania wojen, sporów, kłótni, swarów, sprzeczek, podziałów, prostactwa, szorstkości, grubiaństwa, pospolitości i chamstwa, który przychodzi przeciwko nam, przeciwko mnie i przeciwko naszemu zborowi. Wiążę cię i rozkazuję ci odejść od nas, z mojego domu, z mojej rodziny, z moich relacji, w imieniu Pana Jezusa Chrystusa, mocą Ducha Świętego.\n\nBiorę moc i biorę władzę, i błogosławię moje nogi, moje relacje, nasze zgromadzenia, nabożeństwa i mój dom ku pokojowi, ku chodzeniu drogą Pana, ku radowaniu się i weselu. Jest napisane: Oto daję wam moc stąpania po wężach, skorpionach i po wszelkiej mocy nieprzyjaciela (Łk 10,19), a są one duchowe. I oświadczam, że nie mogą mi zaszkodzić i są wobec mnie bezsilne. Jezus Chrystus jest Panem pokoju, i jest napisane: A Bóg pokoju wkrótce zetrze szatana pod waszymi stopami. (Rz 16,20)\n\nBiorę tarczę wiary, którą gaszę wszystkie ogniste strzały szatana w imieniu Jezusa Chrystusa. Mieszka we mnie wiara, która zwycięża świat. Oświadczam, że także dziś zwyciężam świat i to, co jest na świecie: pożądliwość ciała, pożądliwość oczu, pychę i chełpliwość życia, pokusy, przekleństwo, lęki, nienawiść, niepokoje, strachy, cynizm, krytykanctwo, niewiarę; głupie myśli, żeby nie wypowiadać tego wyznania. Nie staję się większym człowiekiem, jeśli odrzucam to wyznanie. Jestem dzieckiem Bożym. Jest napisane: Jeśli się nie nawrócicie i nie staniecie się jak dzieci, nie wejdziecie do królestwa niebieskiego. (Mt 18,3) Jeśli wynoszę się ponad Słowo Boże, kamień spadnie na mnie tak, jak jest napisane u proroka Daniela: Patrzyłeś na to, aż został odcięty kamień bez pomocy rąk, i uderzył posąg w jego stopy z żelaza i gliny, i skruszył je. (Dn 2,34) Dlatego postanawiam z miękkim sercem poddać się Słowu Bożemu. Panie, jeśli Ty to mówisz, to zrobię to z radością. Cokolwiek mówisz, Panie, zrobię to, bo Ty to mówisz. Kocham Słowo Boże i wypełniam je. Owca, która się nie pasie, ginie. Dlatego postanawiam jeść Słowo Boże; każdego dnia karmię mojego ducha. W imieniu Pana Jezusa przez wiarę zwyciężam myśli niewiary. W imieniu Jezusa Chrystusa przez wiarę przeciwstawiam się złemu, i ucieka ode mnie, bo jest napisane: przeciwstawcie się diabłu, a ucieknie od was. (Jk 4,7) Przez wiarę szukam królestwa Bożego i Jego sprawiedliwości, a Ty mnie napełniasz, zaspokajasz każdą moją potrzebę. Przez wiarę rozkoszuję się Tobą, Panie Jezu Chryste. Spełniasz wszystkie pragnienia mojego serca. Przez wiarę idę od mocy do mocy, od zwycięstwa do zwycięstwa, od chwały do chwały. Przez wiarę mówię nowymi językami, przez wiarę prorokuję, w potężnym imieniu Pana Jezusa Chrystusa. Przez wiarę w imieniu Pana Jezusa Chrystusa kładę ręce na chorych, a oni wyzdrowieją. Przez wiarę w imieniu Pana Jezusa Chrystusa wypędzam demony. Jeśli wypiję coś zabójczego albo wezmę węże, i one mi nie zaszkodzą. Przez wiarę, z łaski, mój Bóg strzeże mnie swoją mocą ku zbawieniu. Amen. (Wyznanie: Hebrajczyków 11, fragmenty o bohaterach wiary.)\n\nW imieniu Pana Jezusa poddaję się słowu Bożemu i oddaję Bogu szczególnie mój język, moje usta. Błogosławię was, moje usta, w imieniu Jezusa, aby mowa Boża, Słowo Boże, wychodziło z was także dziś jak miecz obosieczny, jak młot kruszący skałę, duch i życie, ogień pożerający, prawda, pokój, przez moc, władzę i namaszczenie Ducha Świętego. Niech będzie ku nowemu narodzeniu, ku znakom i cudom dla słuchających i także dla mnie, w potężnym i chwalebnym imieniu Jezusa Chrystusa. Amen. Alleluja!\n\nNa to wszystko przywdziewam szatę i płaszcz chwały, i zniechęcenie odeszło ode mnie, a sio! W imieniu Jezusa. Alleluja!\n\nTe wyznania trzeba wypowiadać każdego dnia. Trzeba też w imieniu Jezusa brać władzę nad dniami i świętami. Od stuleci złe duchy panują nad dniami, świętami, miastami, wsiami, krajami, narodami, ludźmi. Słowem Bożym trzeba brać władzę nad duchowymi twierdzami. Z góry jestem na wojnie! Tylko wtedy, gdy każdego dnia przywdziewam duchową broń, te złe duchy nie mogą mi zaszkodzić. Na moją rodzinę, mój dom, moją pracę i na wszystko, co mam, trzeba położyć ochronę Pana Jezusa i prosić aniołów, aby przyszli i strzegli nas.\n\nW imieniu Pana Jezusa, mocą Ducha Świętego, biorę władzę i wiążę wszelką szatańską moc nad moim dzisiejszym dniem! Moje życie, mój dom, moją rodzinę oddaję pod ochronę krwi Jezusa.\n\nW imieniu Pana Jezusa wiążę czary, urok, ducha Jezabel, religijną mgłę, antychrysta, materializm. Złe duchy niewiary, przekleństwa, ubóstwa, fałszywego ducha, fałszywego bólu, kłamliwego objawu, ducha choroby, zwątpienia, niemocy, horoskopu, okultyzmu, jogi, śmierci, piekła i odrzucenia, w imieniu Jezusa wiążę was i rozkazuję wam: wyjdźcie ze mnie, zejdźcie ze mnie, z mojej rodziny, z mojego domu, z mojego życia, z mojego losu, z mojego ludu, z mojego narodu, w imieniu Jezusa, mocą Ducha Świętego. Mój dzisiejszy dzień oddaję chwale Bożej.\n\nWyznanie:\n\nMoje ciało jest świątynią Ducha Świętego, odkupione, oczyszczone, uświęcone krwią Jezusa. Moje członki są częściami ciała, narzędziami sprawiedliwości, oddanymi Bogu na Jego służbę i dla Jego chwały. Trzymam oko skierowane na jeden cel, i całe moje ciało jest pełne światła. Diabeł nie ma we mnie miejsca, nie ma nade mną władzy i nie ma wobec mnie żadnych słusznych roszczeń. Krew Jezusa wszystko załatwiła; On zwyciężył szatana przez krew Baranka. Moje świadectwo jest takie: sam Jezus poniósł moje grzechy na swoim ciele na drzewo, abym, obumarłszy grzechom, żył dla sprawiedliwości; przez Jego rany mam uzdrowienie. Amen. Chwała Panu Jezusowi Chrystusowi, który siedzi po prawicy Ojca!", "kepek": [{"f": "10-feher-ruha.webp", "mondat": "dziękuję Ci za Twoją miłość", "utana": true}, {"f": "1-sisak.webp", "mondat": "Przywdziewam hełm zbawienia i nadziei", "nev": "hełm zbawienia i nadziei"}, {"f": "2-mellvert.webp", "mondat": "przywdziewam pancerz sprawiedliwości", "nev": "pancerz sprawiedliwości i usprawiedliwienia"}, {"f": "3-ov.webp", "mondat": "Przepasuję moje biodra prawością", "nev": "biodra prawością"}, {"f": "4-saru.webp", "mondat": "Obuwam moje nogi", "nev": "gotowość ewangelii pokoju"}, {"f": "5-pajzs.webp", "mondat": "Biorę tarczę wiary", "nev": "tarczę wiary"}, {"f": "6-kard.webp", "mondat": "poddaję się słowu Bożemu", "nev": "miecz obosieczny"}, {"f": "7-palast.webp", "mondat": "przywdziewam szatę i płaszcz chwały", "nev": "szatę i płaszcz chwały"}, {"f": "9-tiszt.webp", "mondat": "Na to wszystko przywdziewam", "utana": true}]};


