  "Kezdőlap: a Biblia- és a játékcsempék képei akkor is betöltődnek, ha a telefon egy helyi (Bluetooth) szobához kapcsolódik.": "Strona startowa: obrazy kafelków Biblii i gier wczytują się także wtedy, gdy telefon jest połączony z pokojem lokalnym (Bluetooth).",
  "Rezgés: azokon a telefonokon, amelyek a finom koppintást nem érzékeltetik, erősebb és hosszabb rezgés jelzi az érintést.": "Wibracje: na telefonach, które nie oddają delikatnego stuknięcia, dotyk sygnalizuje mocniejsza i dłuższa wibracja.",
  "Biblia: a napi időbe csak az olvasás és a felolvasás hallgatása számít bele, a jegyzetírás és a keresés nem.": "Biblia: do czasu dziennego liczy się tylko czytanie i słuchanie czytania, a nie pisanie notatek i wyszukiwanie.",
